import { motion } from 'framer-motion'
import PropTypes from 'prop-types'
import { FaExclamationTriangle, FaShieldAlt, FaUserLock, FaUserClock, FaProjectDiagram, FaCheckCircle, FaKey, FaArrowRight } from 'react-icons/fa'

const severityStyles = {
  critical: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300',
  warning: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300',
  info: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300'
}

const QueueSummaryCard = ({ label, value, tone = 'neutral', onClick }) => {
  const toneClass =
    tone === 'critical'
      ? 'border-red-200 bg-red-50 text-red-700 dark:border-red-900/40 dark:bg-red-900/20 dark:text-red-300'
      : tone === 'warning'
        ? 'border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900/40 dark:bg-amber-900/20 dark:text-amber-300'
        : 'border-gray-200 bg-gray-50 text-gray-700 dark:border-gray-700 dark:bg-gray-900/40 dark:text-gray-200'

  return (
    <button type='button' onClick={onClick} className={`rounded-lg border p-4 text-left transition-colors hover:border-accent/40 hover:bg-accent/5 ${toneClass}`}>
      <p className='text-xs font-semibold uppercase tracking-wide opacity-80'>{label}</p>
      <div className='mt-2 flex items-center justify-between gap-3'>
        <span className='text-2xl font-bold'>{value}</span>
        <span className='inline-flex items-center gap-2 text-xs font-medium text-accent'>
          <span>Open</span>
          <FaArrowRight className='w-3 h-3' />
        </span>
      </div>
    </button>
  )
}

const HealthCard = ({ label, value, icon, actionLabel, onAction }) => (
  <div className='rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-4'>
    <div className='flex items-center justify-between'>
      <p className='text-sm text-gray-500 dark:text-gray-400'>{label}</p>
      <span className='text-accent'>{icon}</span>
    </div>
    <p className='text-2xl font-bold text-gray-900 dark:text-white mt-2'>{value}</p>
    {actionLabel && onAction && (
      <button type='button' onClick={onAction} className='mt-3 inline-flex items-center gap-2 text-sm font-medium text-accent hover:text-accent/80 transition-colors'>
        <span>{actionLabel}</span>
        <FaArrowRight className='w-3 h-3' />
      </button>
    )}
  </div>
)

const getAlertAction = (alertId, onOpenSection) => {
  if (!onOpenSection) return null

  if (alertId === 'locked-users') {
    return {
      label: 'Review locked users',
      onClick: () => onOpenSection('users', { status: 'locked' })
    }
  }

  if (alertId === 'inactive-users') {
    return {
      label: 'Review inactive users',
      onClick: () => onOpenSection('users', { status: 'inactive' })
    }
  }

  if (alertId === 'unverified-users') {
    return {
      label: 'Review unverified users',
      onClick: () => onOpenSection('users', { verification: 'unverified' })
    }
  }

  if (alertId === 'password-reset-required-users') {
    return {
      label: 'Review reset-required users',
      onClick: () => onOpenSection('users', { passwordResetRequired: 'true' })
    }
  }

  if (alertId === 'stalled-projects') {
    return {
      label: 'Review stalled projects',
      onClick: () => onOpenSection('projects', { stalled: 'true' })
    }
  }

  return null
}

const getQueueSummaryCards = (signals, onOpenSection) => [
  {
    key: 'locked-users',
    label: 'Locked Users',
    value: signals.lockedUsers || 0,
    tone: (signals.lockedUsers || 0) >= 15 ? 'critical' : (signals.lockedUsers || 0) > 0 ? 'warning' : 'neutral',
    onClick: () => onOpenSection?.('users', { status: 'locked' })
  },
  {
    key: 'inactive-users',
    label: 'Inactive Users',
    value: signals.inactiveUsers || 0,
    tone: (signals.inactiveUsers || 0) >= 50 ? 'critical' : (signals.inactiveUsers || 0) > 0 ? 'warning' : 'neutral',
    onClick: () => onOpenSection?.('users', { status: 'inactive' })
  },
  {
    key: 'unverified-users',
    label: 'Unverified Users',
    value: signals.unverifiedUsers || 0,
    tone: (signals.unverifiedUsers || 0) >= 25 ? 'critical' : (signals.unverifiedUsers || 0) > 0 ? 'warning' : 'neutral',
    onClick: () => onOpenSection?.('users', { verification: 'unverified' })
  },
  {
    key: 'password-reset-required-users',
    label: 'Reset Required',
    value: signals.passwordResetRequiredUsers || 0,
    tone: (signals.passwordResetRequiredUsers || 0) >= 15 ? 'critical' : (signals.passwordResetRequiredUsers || 0) > 0 ? 'warning' : 'neutral',
    onClick: () => onOpenSection?.('users', { passwordResetRequired: 'true' })
  },
  {
    key: 'stalled-projects',
    label: 'Stalled Projects',
    value: signals.stalledProjects || 0,
    tone: (signals.stalledProjects || 0) >= 15 ? 'critical' : (signals.stalledProjects || 0) > 0 ? 'warning' : 'neutral',
    onClick: () => onOpenSection?.('projects', { stalled: 'true' })
  }
]

const AdminAlertsPanel = ({ isLoading, alertSummary, alerts, healthSignals, onOpenSection }) => {
  if (isLoading) {
    return (
      <div className='mt-8 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-6'>
        <div className='h-40 animate-pulse bg-gray-200 dark:bg-gray-700 rounded-lg' />
      </div>
    )
  }

  const summary = alertSummary || { total: 0, critical: 0, warning: 0, info: 0 }
  const list = Array.isArray(alerts) ? alerts : []
  const signals = healthSignals || {
    lockedUsers: 0,
    inactiveUsers: 0,
    unverifiedUsers: 0,
    passwordResetRequiredUsers: 0,
    stalledProjects: 0
  }
  const queueSummaryCards = getQueueSummaryCards(signals, onOpenSection)

  return (
    <motion.section className='mt-8 grid grid-cols-1 xl:grid-cols-3 gap-6' initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25 }}>
      <div className='xl:col-span-2 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-6'>
        <div className='flex flex-col gap-3 mb-4 lg:flex-row lg:items-center lg:justify-between'>
          <div>
            <div className='flex items-center gap-2'>
              <FaExclamationTriangle className='text-amber-500' />
              <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>Action Queue</h3>
            </div>
            <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>Priority admin issues that can be reviewed directly from the dashboard.</p>
          </div>
          <div className='flex items-center gap-2 text-xs'>
            <span className='px-2 py-1 rounded-full bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200'>Total: {summary.total}</span>
            <span className='px-2 py-1 rounded-full bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300'>Critical: {summary.critical}</span>
            <span className='px-2 py-1 rounded-full bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300'>Warning: {summary.warning}</span>
          </div>
        </div>

        <div className='mb-4 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-3'>
          {queueSummaryCards.map((card) => (
            <QueueSummaryCard key={card.key} label={card.label} value={card.value} tone={card.tone} onClick={card.onClick} />
          ))}
        </div>

        {!list.length ? (
          <div className='rounded-lg border border-green-200 dark:border-green-900/40 bg-green-50 dark:bg-green-900/20 p-4 text-green-800 dark:text-green-300 text-sm'>No active alerts. System health looks stable.</div>
        ) : (
          <div className='space-y-3'>
            {list.map((alert) => {
              const action = getAlertAction(alert.id, onOpenSection)

              return (
                <div key={alert.id} className='rounded-lg border border-gray-200 dark:border-gray-700 p-4 bg-gray-50 dark:bg-gray-900/40'>
                  <div className='flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between'>
                    <div>
                      <p className='font-semibold text-gray-900 dark:text-white'>{alert.title}</p>
                      <p className='text-sm text-gray-600 dark:text-gray-300 mt-1'>{alert.message}</p>
                    </div>

                    <div className='flex items-center gap-2'>
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${severityStyles[alert.severity] || severityStyles.info}`}>{alert.severity || 'info'}</span>
                      {action && (
                        <button
                          type='button'
                          onClick={action.onClick}
                          className='inline-flex items-center gap-2 rounded-lg border border-accent/30 bg-accent/10 px-3 py-2 text-xs font-medium text-accent hover:bg-accent/15 transition-colors'>
                          <span>{action.label}</span>
                          <FaArrowRight className='w-3 h-3' />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>

      <div className='rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-6'>
        <div className='flex items-center gap-2 mb-4'>
          <FaShieldAlt className='text-accent' />
          <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>Health Signals</h3>
        </div>

        <div className='space-y-3'>
          <HealthCard label='Locked Users' value={signals.lockedUsers || 0} icon={<FaUserLock />} actionLabel='Open locked users' onAction={() => onOpenSection?.('users', { status: 'locked' })} />
          <HealthCard label='Inactive Users (14+ d)' value={signals.inactiveUsers || 0} icon={<FaUserClock />} actionLabel='Open inactive users' onAction={() => onOpenSection?.('users', { status: 'inactive' })} />
          <HealthCard
            label='Unverified Users'
            value={signals.unverifiedUsers || 0}
            icon={<FaCheckCircle />}
            actionLabel='Open unverified users'
            onAction={() => onOpenSection?.('users', { verification: 'unverified' })}
          />
          <HealthCard
            label='Password Reset Required'
            value={signals.passwordResetRequiredUsers || 0}
            icon={<FaKey />}
            actionLabel='Open reset-required users'
            onAction={() => onOpenSection?.('users', { passwordResetRequired: 'true' })}
          />
          <HealthCard
            label='Stalled Projects (14+ d)'
            value={signals.stalledProjects || 0}
            icon={<FaProjectDiagram />}
            actionLabel='Open stalled projects'
            onAction={() => onOpenSection?.('projects', { stalled: 'true' })}
          />
        </div>
      </div>
    </motion.section>
  )
}

AdminAlertsPanel.propTypes = {
  isLoading: PropTypes.bool,
  alertSummary: PropTypes.shape({}),
  alerts: PropTypes.array,
  healthSignals: PropTypes.shape({}),
  onOpenSection: PropTypes.func
}

export default AdminAlertsPanel

import { useEffect, useState } from 'react'
import { motion } from 'framer-motion'
import { FaHistory, FaSearch } from 'react-icons/fa'
import PaginationControls from '../shared/PaginationControls'
import { getAdminAuditLogs } from '../../services/userService'

const formatActionLabel = (value = '') =>
  value
    .split('.')
    .map((part) => (part ? part.charAt(0).toUpperCase() + part.slice(1) : ''))
    .join(' ')

const formatTargetTypeLabel = (value = '') =>
  value
    .split('_')
    .map((part) => (part ? part.charAt(0).toUpperCase() + part.slice(1) : ''))
    .join(' ')

const formatActorName = (actor) => {
  if (!actor) return 'Unknown admin'
  const fullName = `${actor.firstName || ''} ${actor.lastName || ''}`.trim()
  return fullName || actor.email || 'Unknown admin'
}

const formatChangeValue = (value) => {
  if (value === null || value === undefined || value === '') return 'Empty'
  if (Array.isArray(value)) return value.join(', ') || 'Empty'
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

const severityToneByAction = {
  'user.deleted': 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300',
  'project.cancelled': 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300',
  'project.locked': 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300',
  'blog.deleted': 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300'
}

const AdminAuditLogPanel = () => {
  const [logs, setLogs] = useState([])
  const [filterOptions, setFilterOptions] = useState({ actions: [], targetTypes: [] })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')
  const [selectedAction, setSelectedAction] = useState('')
  const [selectedTargetType, setSelectedTargetType] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [total, setTotal] = useState(0)

  useEffect(() => {
    setCurrentPage(1)
  }, [search, selectedAction, selectedTargetType])

  useEffect(() => {
    fetchAuditLogs()
  }, [currentPage, search, selectedAction, selectedTargetType])

  const fetchAuditLogs = async () => {
    try {
      setLoading(true)
      setError('')

      const data = await getAdminAuditLogs({
        page: currentPage,
        limit: 10,
        search,
        action: selectedAction,
        targetType: selectedTargetType
      })

      setLogs(Array.isArray(data?.logs) ? data.logs : [])
      setTotalPages(data?.pages || 1)
      setTotal(data?.total || 0)
      setFilterOptions({
        actions: Array.isArray(data?.filterOptions?.actions) ? data.filterOptions.actions : [],
        targetTypes: Array.isArray(data?.filterOptions?.targetTypes) ? data.filterOptions.targetTypes : []
      })
    } catch (err) {
      console.error('Error fetching audit logs:', err)
      setError(err.response?.data?.message || 'Failed to load audit logs.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <motion.section className='mt-8 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-6' initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25 }}>
      <div className='flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between mb-6'>
        <div className='flex items-center gap-3'>
          <div className='rounded-lg bg-accent/10 p-3 text-accent'>
            <FaHistory />
          </div>
          <div>
            <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>Admin Audit Log</h3>
            <p className='text-sm text-gray-500 dark:text-gray-400'>Recent admin actions across users, projects, and blog content.</p>
          </div>
        </div>

        <div className='text-sm text-gray-500 dark:text-gray-400'>
          Total entries: <span className='font-semibold text-gray-900 dark:text-white'>{total}</span>
        </div>
      </div>

      <div className='grid grid-cols-1 lg:grid-cols-3 gap-4 mb-6'>
        <div className='relative'>
          <input
            type='text'
            placeholder='Search summary or target...'
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className='w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-900 dark:text-white'
          />
          <FaSearch className='absolute left-3 top-3 text-gray-400' />
        </div>

        <select
          value={selectedAction}
          onChange={(e) => setSelectedAction(e.target.value)}
          className='w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-900 dark:text-white'>
          <option value=''>All Actions</option>
          {filterOptions.actions.map((action) => (
            <option key={action} value={action}>
              {formatActionLabel(action)}
            </option>
          ))}
        </select>

        <select
          value={selectedTargetType}
          onChange={(e) => setSelectedTargetType(e.target.value)}
          className='w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-900 dark:text-white'>
          <option value=''>All Targets</option>
          {filterOptions.targetTypes.map((targetType) => (
            <option key={targetType} value={targetType}>
              {formatTargetTypeLabel(targetType)}
            </option>
          ))}
        </select>
      </div>

      {loading && <div className='rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/40 p-6 text-sm text-gray-500 dark:text-gray-300'>Loading audit log...</div>}

      {error && <div className='rounded-lg border border-red-200 dark:border-red-900/40 bg-red-50 dark:bg-red-900/20 p-4 text-sm text-red-700 dark:text-red-300'>{error}</div>}

      {!loading && !error && logs.length === 0 && (
        <div className='rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/40 p-6 text-sm text-gray-500 dark:text-gray-300'>No audit log entries found for the current filters.</div>
      )}

      {!loading && !error && logs.length > 0 && (
        <div className='space-y-4'>
          {logs.map((log) => (
            <div key={log._id} className='rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/40 p-4'>
              <div className='flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between'>
                <div className='space-y-2'>
                  <div className='flex flex-wrap items-center gap-2'>
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${severityToneByAction[log.action] || 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300'}`}>
                      {formatActionLabel(log.action)}
                    </span>
                    <span className='px-2 py-1 rounded-full text-xs font-medium bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-200'>
                      {formatTargetTypeLabel(log.targetType)}
                    </span>
                    <span className='text-xs text-gray-500 dark:text-gray-400'>{new Date(log.createdAt).toLocaleString()}</span>
                  </div>

                  <div>
                    <p className='font-semibold text-gray-900 dark:text-white'>{log.summary}</p>
                    <p className='text-sm text-gray-600 dark:text-gray-300 mt-1'>
                      By {formatActorName(log.actor)}
                      {log.targetLabel ? ` on ${log.targetLabel}` : ''}
                    </p>
                  </div>

                  {Array.isArray(log.changes) && log.changes.length > 0 && (
                    <div className='rounded-md border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-3'>
                      <p className='text-xs font-semibold uppercase tracking-wide text-gray-500 dark:text-gray-400 mb-2'>Field Changes</p>
                      <div className='space-y-2'>
                        {log.changes.map((change, index) => (
                          <div key={`${log._id}-${change.field}-${index}`} className='text-sm text-gray-700 dark:text-gray-300'>
                            <span className='font-medium text-gray-900 dark:text-white'>{change.field}:</span> {formatChangeValue(change.before)} {' -> '} {formatChangeValue(change.after)}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>

                <div className='text-xs text-gray-500 dark:text-gray-400 lg:text-right'>
                  <div>Actor Role: {formatTargetTypeLabel(log.actorRole || 'unknown')}</div>
                  {log.context?.ipAddress && <div className='mt-1'>IP: {log.context.ipAddress}</div>}
                </div>
              </div>
            </div>
          ))}

          <PaginationControls currentPage={currentPage} totalPages={totalPages} onPrev={() => setCurrentPage((prev) => Math.max(1, prev - 1))} onNext={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))} label={`Page ${currentPage} of ${totalPages}`} />
        </div>
      )}
    </motion.section>
  )
}

export default AdminAuditLogPanel

import { useEffect, useState } from 'react'
import { FaTrash, FaToggleOn, FaToggleOff, FaSyncAlt, FaNewspaper, FaPlus, FaPen } from 'react-icons/fa'
import { toast } from 'react-toastify'
import { useAuth } from '../../context/AuthContext'
import { createBlogPost, deleteBlogPost, getAdminBlogPosts, toggleBlogPostPublish, updateBlogPost } from '../../services/blogService'
import AdminBlogPostModal from '../../modal/AdminBlogPostModal'
import PublishedBadge from '../shared/PublishedBadge'

const AdminBlogPostsList = () => {
  const { currentUser } = useAuth()
  const [posts, setPosts] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [actionLoadingId, setActionLoadingId] = useState(null)
  const [isEditorOpen, setIsEditorOpen] = useState(false)
  const [editorMode, setEditorMode] = useState('create')
  const [selectedPost, setSelectedPost] = useState(null)
  const [isEditorSubmitting, setIsEditorSubmitting] = useState(false)

  const fetchPosts = async () => {
    try {
      setLoading(true)
      setError('')
      const data = await getAdminBlogPosts()
      setPosts(Array.isArray(data) ? data : [])
    } catch (err) {
      console.error('Failed to load blog posts:', err)
      setError(err.response?.data?.message || 'Failed to load blog posts')
      toast.error('Failed to load blog posts')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchPosts()
  }, [])

  const handleTogglePublish = async (post) => {
    const nextAction = post.isPublished ? 'unpublish' : 'publish'
    const confirmed = window.confirm(`Are you sure you want to ${nextAction} "${post.title}"?`)
    if (!confirmed) return

    try {
      setActionLoadingId(post._id)
      await toggleBlogPostPublish(post._id)
      toast.success(`Blog post ${nextAction}ed successfully`)
      await fetchPosts()
    } catch (err) {
      toast.error(err.response?.data?.message || `Failed to ${nextAction} blog post`)
    } finally {
      setActionLoadingId(null)
    }
  }

  const handleDelete = async (post) => {
    const confirmed = window.confirm(`Delete blog post "${post.title}"?\n\nThis cannot be undone.`)
    if (!confirmed) return

    try {
      setActionLoadingId(post._id)
      await deleteBlogPost(post._id)
      toast.success('Blog post deleted successfully')
      await fetchPosts()
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to delete blog post')
    } finally {
      setActionLoadingId(null)
    }
  }

  const handleOpenCreate = () => {
    setEditorMode('create')
    setSelectedPost(null)
    setIsEditorOpen(true)
  }

  const handleOpenEdit = (post) => {
    setEditorMode('edit')
    setSelectedPost(post)
    setIsEditorOpen(true)
  }

  const handleCloseEditor = () => {
    setIsEditorOpen(false)
    setSelectedPost(null)
    setEditorMode('create')
  }

  const handleEditorSubmit = async (payload, submitMode) => {
    try {
      setIsEditorSubmitting(true)

      if (editorMode === 'edit' && selectedPost?._id) {
        await updateBlogPost(selectedPost._id, payload)
        toast.success(`Blog post ${submitMode === 'publish' ? 'updated and published' : 'updated'} successfully`)
      } else {
        await createBlogPost(payload)
        toast.success(`Blog post ${submitMode === 'publish' ? 'created and published' : 'saved as draft'} successfully`)
      }

      handleCloseEditor()
      await fetchPosts()
    } catch (err) {
      console.error('Failed to save blog post:', err)
      toast.error(err.response?.data?.message || 'Failed to save blog post')
    } finally {
      setIsEditorSubmitting(false)
    }
  }

  const formatDate = (value) => {
    if (!value) return 'N/A'
    const date = new Date(value)
    if (Number.isNaN(date.getTime())) return 'N/A'
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    })
  }

  const publishedCount = posts.filter((post) => post.isPublished).length
  const draftCount = posts.length - publishedCount

  const getDisplayAuthor = (post) => {
    if (post?.showAuthor === false) return 'Hidden'

    if (post?.authorName?.trim()) return post.authorName.trim()

    if (post?.author) {
      const fullName = `${post.author.firstName || ''} ${post.author.lastName || ''}`.trim()
      if (fullName) return fullName
    }

    return 'Unknown'
  }

  return (
    <div>
      <div className='flex items-center justify-between mb-6'>
        <div>
          <h2 className='text-2xl font-bold text-gray-900 dark:text-white'>Blog Management</h2>
          <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>Manage published posts and drafts for the public blog</p>
        </div>

        <div className='flex items-center gap-3'>
          <button onClick={handleOpenCreate} className='px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 transition-all text-sm font-medium inline-flex items-center gap-2'>
            <FaPlus />
            New Post
          </button>

          <button
            onClick={fetchPosts}
            className='px-4 py-2 border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 transition-all text-sm font-medium inline-flex items-center gap-2'>
            <FaSyncAlt />
            Refresh
          </button>
        </div>
      </div>

      <div className='grid grid-cols-1 md:grid-cols-3 gap-4 mb-6'>
        <div className='bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4'>
          <p className='text-sm text-gray-500 dark:text-gray-400'>Total Posts</p>
          <p className='text-2xl font-bold text-gray-900 dark:text-white'>{posts.length}</p>
        </div>

        <div className='bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4'>
          <p className='text-sm text-gray-500 dark:text-gray-400'>Published</p>
          <p className='text-2xl font-bold text-green-600'>{publishedCount}</p>
        </div>

        <div className='bg-white dark:bg-gray-800 rounded-lg shadow-sm p-4'>
          <p className='text-sm text-gray-500 dark:text-gray-400'>Drafts</p>
          <p className='text-2xl font-bold text-amber-600'>{draftCount}</p>
        </div>
      </div>

      <div className='bg-white dark:bg-gray-800 rounded-lg shadow-sm overflow-hidden'>
        {loading && (
          <div className='flex items-center justify-center py-12'>
            <div className='animate-spin rounded-full h-12 w-12 border-b-2 border-accent'></div>
          </div>
        )}

        {!loading && error && (
          <div className='p-8 text-center'>
            <p className='text-red-600 dark:text-red-400'>{error}</p>
            <button onClick={fetchPosts} className='mt-4 px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90'>
              Try Again
            </button>
          </div>
        )}

        {!loading && !error && posts.length === 0 && (
          <div className='p-10 text-center text-gray-500 dark:text-gray-400'>
            <FaNewspaper className='mx-auto mb-4 text-4xl opacity-40' />
            No blog posts found
          </div>
        )}

        {!loading && !error && posts.length > 0 && (
          <div className='overflow-x-auto'>
            <table className='w-full'>
              <thead className='bg-gray-50 dark:bg-gray-700'>
                <tr>
                  <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Post</th>
                  <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Slug</th>
                  <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Author</th>
                  <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Status</th>
                  <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Published</th>
                  <th className='px-6 py-3 text-right text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Actions</th>
                </tr>
              </thead>

              <tbody className='bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700'>
                {posts.map((post) => {
                  const isBusy = actionLoadingId === post._id

                  return (
                    <tr key={post._id} className='hover:bg-gray-50 dark:hover:bg-gray-700'>
                      <td className='px-6 py-4'>
                        <div className='text-sm font-medium text-gray-900 dark:text-white'>{post.title}</div>
                        <div className='text-sm text-gray-500 dark:text-gray-400 mt-1 line-clamp-2'>{post.excerpt}</div>
                      </td>

                      <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>{post.slug}</td>

                      <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-900 dark:text-white'>{getDisplayAuthor(post)}</td>

                      <td className='px-6 py-4 whitespace-nowrap'>
                        <PublishedBadge isPublished={post.isPublished} />
                      </td>

                      <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>{formatDate(post.publishedAt)}</td>

                      <td className='px-6 py-4 whitespace-nowrap text-right text-sm font-medium'>
                        <div className='flex items-center justify-end gap-2'>
                          <button onClick={() => handleOpenEdit(post)} disabled={isBusy} className='text-blue-600 hover:text-blue-900 dark:text-blue-400 dark:hover:text-blue-300 disabled:opacity-50' title='Edit'>
                            <FaPen />
                          </button>

                          <button
                            onClick={() => handleTogglePublish(post)}
                            disabled={isBusy}
                            className={`${post.isPublished ? 'text-amber-600 hover:text-amber-900' : 'text-green-600 hover:text-green-900'} disabled:opacity-50`}
                            title={post.isPublished ? 'Unpublish' : 'Publish'}>
                            {post.isPublished ? <FaToggleOn size={20} /> : <FaToggleOff size={20} />}
                          </button>

                          <button onClick={() => handleDelete(post)} disabled={isBusy} className='text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-300 disabled:opacity-50' title='Delete'>
                            <FaTrash />
                          </button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <AdminBlogPostModal isOpen={isEditorOpen} mode={editorMode} post={selectedPost} currentUser={currentUser} isSubmitting={isEditorSubmitting} onClose={handleCloseEditor} onSubmit={handleEditorSubmit} />
    </div>
  )
}

export default AdminBlogPostsList

import { FaSearch, FaFilter, FaPlus, FaEdit, FaTrash, FaLock, FaEye, FaCalendarAlt } from 'react-icons/fa'
import PropTypes from 'prop-types'
import { useState, useEffect, useRef } from 'react'
import { toast } from 'react-toastify'
import ProjectModal from '../../modal/ProjectModal'
import AdminProjectCancelModal from '../../modal/AdminProjectCancelModal'
import AdminProjectEditModal from '../../modal/AdminProjectEditModal'
import AdminProjectDetailModal from '../../modal/AdminProjectDetailModal'
import AdminLockProjectModal from '../../modal/AdminLockProjectModal'
import PaginationControls from '../shared/PaginationControls'
import { getAdminAllProjects, deleteProjectAsAdmin, updateProjectAsAdmin, bulkRenewProjectDeadlinesAsAdmin, toggleProjectLockAsAdmin, removeAssigneeAsAdmin } from '../../services/projectService'
import PriorityBadge from '../shared/PriorityBadge'
import ProjectStatusBadge from '../shared/ProjectStatusBadge'
import { formatProjectStatusLabel } from '../../utils/projectStatusUI'
import { useAuth } from '../../context/AuthContext'
import { ADMIN_PERMISSIONS, hasAdminPermission, isFullAdmin } from '../../utils/accessRoles'

const ProgressBar = ({ progress }) => (
  <div className='w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700 mt-2'>
    <div className='bg-accent h-2.5 rounded-full transition-all duration-300' style={{ width: `${progress}%` }} />
  </div>
)

const TeamAvatars = ({ team }) => (
  <div className='flex -space-x-2'>
    {team.map((member, index) => (
      <div key={index} className='w-8 h-8 rounded-full bg-accent text-white flex items-center justify-center text-xs border-2 border-white dark:border-gray-800' title={member}>
        {member
          .split(' ')
          .map((n) => n[0])
          .join('')}
      </div>
    ))}
  </div>
)

const AdminProjectsList = ({ navigationRequest }) => {
  // State
  const [selectedStatus, setSelectedStatus] = useState('All')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('All')
  const [selectedPriority, setPriority] = useState('All')
  const [dateRange, setDateRange] = useState({
    start: '',
    end: ''
  })
  const [stalledOnly, setStalledOnly] = useState(false)
  const latestProjectsFetchRef = useRef(0)
  const [activePresetLabel, setActivePresetLabel] = useState('')
  const [selectedProjects, setSelectedProjects] = useState([])
  const [bulkRenewalDate, setBulkRenewalDate] = useState('')
  const [quickRenewProjectId, setQuickRenewProjectId] = useState(null)
  const [quickRenewalDate, setQuickRenewalDate] = useState('')

  const [sortBy, setSortBy] = useState('createdAt:desc')
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(30)
  const [isNewProjectModalOpen, setIsNewProjectModalOpen] = useState(false)
  const [lockLoadingProjectId, setLockLoadingProjectId] = useState(null)
  const [isLockModalOpen, setIsLockModalOpen] = useState(false)
  const [projectToLock, setProjectToLock] = useState(null)

  // Data
  const [projectsData, setProjectsData] = useState([])
  const [overallTotalCount, setOverallTotalCount] = useState(0)
  const [totalFilteredCount, setTotalFilteredCount] = useState(0)
  const [totalPages, setTotalPages] = useState(1)
  const [summaryCounts, setSummaryCounts] = useState({
    total: 0,
    active: 0,
    in_progress: 0,
    under_review: 0,
    completed: 0,
    cancelled: 0
  })
  const [filterOptions, setFilterOptions] = useState({
    statuses: [],
    categories: [],
    priorities: []
  })
  const [error, setError] = useState(null)

  // Delete modal state
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false)
  const [projectToDelete, setProjectToDelete] = useState(null)
  const [deleteLoading, setDeleteLoading] = useState(false)

  // Edit modal state
  const [isEditModalOpen, setIsEditModalOpen] = useState(false)
  const [editingProjectId, setEditingProjectId] = useState(null)
  const [editLoading, setEditLoading] = useState(false)
  const [editForm, setEditForm] = useState({
    title: '',
    description: '',
    category: '',
    skills: '',
    budget: '',
    priority: 'low',
    deadline: '',
    status: 'active'
  })
  const [removeAssigneeLoading, setRemoveAssigneeLoading] = useState(false)
  const [editingProjectMeta, setEditingProjectMeta] = useState({
    assignee: null,
    owner: null
  })

  // Detail modal state
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false)
  const [projectForDetails, setProjectForDetails] = useState(null)

  const statusOptions = ['All', ...filterOptions.statuses]
  const categoryOptions = ['All', ...filterOptions.categories]
  const priorityOptions = ['All', ...filterOptions.priorities]

  // Auth
  const { currentUser } = useAuth()
  const canUpdateProjects = hasAdminPermission(currentUser, ADMIN_PERMISSIONS.PROJECTS_UPDATE_ADMIN)
  const canLockProjects = hasAdminPermission(currentUser, ADMIN_PERMISSIONS.PROJECTS_LOCK_ADMIN)
  const canDeleteProjects = hasAdminPermission(currentUser, ADMIN_PERMISSIONS.PROJECTS_DELETE_ADMIN)
  const canCreateProjects = isFullAdmin(currentUser)

  const fetchProjects = async () => {
    const fetchId = ++latestProjectsFetchRef.current

    try {
      setError(null)

      const response = await getAdminAllProjects({
        search: searchQuery,
        status: selectedStatus === 'All' ? '' : selectedStatus,
        category: selectedCategory === 'All' ? '' : selectedCategory,
        priority: selectedPriority === 'All' ? '' : selectedPriority,
        startDate: dateRange.start,
        endDate: dateRange.end,
        stalled: stalledOnly ? 'true' : '',
        page: currentPage,
        limit: pageSize,
        sort: sortBy
      })

      if (fetchId !== latestProjectsFetchRef.current) return

      const data = response.projects || []

      const mapped = data.map((project) => ({
        id: project._id,
        name: project.title || 'Untitled project',
        title: project.title || 'Untitled project',
        description: project.description || 'No description',
        status: project.status || 'inactive',
        createdAt: project.createdAt || '',
        updatedAt: project.updatedAt || '',
        deadline: project.deadline ? new Date(project.deadline).toISOString().split('T')[0] : '',
        progress: project.status === 'completed' ? 100 : project.status === 'in_progress' ? 65 : project.status === 'under_review' ? 90 : project.status === 'negotiating' ? 35 : project.status === 'assigned' ? 20 : 0,
        priority: project.priority || 'low',
        category: project.category || 'General',
        budget: project.budget ?? null,
        skills: Array.isArray(project.skills) ? project.skills : [],
        attachments: Array.isArray(project.attachments) ? project.attachments : [],
        submission: project.submission || null,
        review: project.review || null,
        interestedUsers: Array.isArray(project.interestedUsers) ? project.interestedUsers : [],
        isRated: Boolean(project.isRated),
        rateNegotiation: project.rateNegotiation || null,
        user: project.user || null,
        assignee: project.assignee || null,
        isLocked: Boolean(project.isLocked),
        lockReason: project.lockReason || '',
        lockDurationDays: project.lockDurationDays ?? null,
        lockExpiresAt: project.lockExpiresAt || null,
        lockedAt: project.lockedAt || null,
        team: [`${project.user?.firstName || ''} ${project.user?.lastName || ''}`.trim() || 'Owner', project.assignee ? `${project.assignee.firstName || ''} ${project.assignee.lastName || ''}`.trim() : null].filter(
          Boolean
        )
      }))

      setProjectsData(mapped)
      setOverallTotalCount(response.overallTotal || 0)
      setTotalFilteredCount(response.total || 0)
      setTotalPages(response.pages || 1)
      setSummaryCounts(response.summaryCounts || { total: 0, active: 0, in_progress: 0, under_review: 0, completed: 0, cancelled: 0 })
      setFilterOptions(response.filterOptions || { statuses: [], categories: [], priorities: [] })
    } catch (err) {
      if (fetchId !== latestProjectsFetchRef.current) return

      console.error('Error fetching admin projects:', err)
      setError('Failed to load projects')
    } finally {
      // fetch completed
    }
  }

  const openDeleteModal = (project) => {
    setProjectToDelete(project)
    setIsDeleteModalOpen(true)
  }

  const closeDeleteModal = () => {
    setProjectToDelete(null)
    setIsDeleteModalOpen(false)
  }

  const openEditModal = (project) => {
    setEditingProjectMeta({
      assignee: project.assignee || null,
      owner: project.user || null
    })
    setEditingProjectId(project.id)
    setEditForm({
      title: project.name || '',
      description: project.description || '',
      category: project.category || '',
      skills: Array.isArray(project.skills) ? project.skills.join(', ') : '',
      budget: project.budget ?? '',
      priority: project.priority || 'low',
      deadline: project.deadline || '',
      status: project.status || 'active'
    })
    setIsEditModalOpen(true)
  }

  const closeEditModal = () => {
    setEditingProjectId(null)
    setIsEditModalOpen(false)
    setRemoveAssigneeLoading(false)
    setEditingProjectMeta({
      assignee: null,
      owner: null
    })
  }

  const openDetailModal = (project) => {
    setProjectForDetails(project)
    setIsDetailModalOpen(true)
  }

  const closeDetailModal = () => {
    setProjectForDetails(null)
    setIsDetailModalOpen(false)
  }

  const openLockModal = (project) => {
    setProjectToLock(project)
    setIsLockModalOpen(true)
  }

  const closeLockModal = () => {
    setProjectToLock(null)
    setIsLockModalOpen(false)
  }

  const handleEditProject = async () => {
    if (!editingProjectId) return

    const title = (editForm.title || '').trim()
    const description = (editForm.description || '').trim()
    const category = (editForm.category || '').trim()
    const skills = String(editForm.skills || '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean)

    if (!title) {
      toast.warning('Project title is required')
      return
    }

    if (!description) {
      toast.warning('Project description is required')
      return
    }

    if (!category) {
      toast.warning('Project category is required')
      return
    }

    if (!editForm.deadline) {
      toast.warning('Project deadline is required')
      return
    }

    if (editForm.budget !== '' && Number(editForm.budget) < 0) {
      toast.error('Budget cannot be negative')
      return
    }

    try {
      setEditLoading(true)

      await updateProjectAsAdmin(editingProjectId, {
        title,
        description,
        category,
        skills,
        budget: editForm.budget === '' ? undefined : Number(editForm.budget),
        priority: editForm.priority,
        deadline: editForm.deadline,
        status: editForm.status
      })

      await fetchProjects()
      closeEditModal()
      toast.success('Project updated successfully')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to update project')
    } finally {
      setEditLoading(false)
    }
  }

  const handleDeleteProject = async () => {
    if (!projectToDelete) return

    try {
      setDeleteLoading(true)
      await deleteProjectAsAdmin(projectToDelete.id)
      await fetchProjects()
      closeDeleteModal()
      toast.success('Project canceled by admin')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to cancel project')
    } finally {
      setDeleteLoading(false)
    }
  }

  const handleToggleProjectLock = async (project) => {
    try {
      setLockLoadingProjectId(project.id)

      if (project.isLocked) {
        const response = await toggleProjectLockAsAdmin(project.id)
        await fetchProjects()
        toast.success(response?.message || 'Project unlocked successfully')
        return
      }

      openLockModal(project)
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to change project lock status')
    } finally {
      setLockLoadingProjectId(null)
    }
  }

  const handleConfirmLockProject = async ({ reason, durationDays }) => {
    if (!projectToLock) return

    try {
      setLockLoadingProjectId(projectToLock.id)
      const response = await toggleProjectLockAsAdmin(projectToLock.id, { reason, durationDays })
      await fetchProjects()
      closeLockModal()
      toast.success(response?.message || 'Project locked successfully')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to lock project')
    } finally {
      setLockLoadingProjectId(null)
    }
  }

  const handleRemoveAssigneeFromEditModal = async () => {
    if (!editingProjectId) {
      toast.error('No project selected')
      return
    }

    if (!editingProjectMeta?.assignee) {
      toast.info('This project has no assignee to remove')
      return
    }

    const fullName = `${editingProjectMeta.assignee.firstName || ''} ${editingProjectMeta.assignee.lastName || ''}`.trim()
    const confirmed = window.confirm(`Remove assignee "${fullName || 'Unknown user'}" from this project?`)
    if (!confirmed) return

    try {
      setRemoveAssigneeLoading(true)
      const response = await removeAssigneeAsAdmin(editingProjectId)
      await fetchProjects()

      setEditingProjectMeta((prev) => ({ ...prev, assignee: null }))

      if (['assigned', 'in_progress', 'negotiating', 'under_review'].includes(editForm.status)) {
        setEditForm((prev) => ({ ...prev, status: 'active' }))
      }

      toast.success(response?.message || 'Assignee removed successfully')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to remove assignee')
    } finally {
      setRemoveAssigneeLoading(false)
    }
  }

  const clearFilters = () => {
    clearAllFilters()
  }

  const isProjectEligibleForRenewal = (project) => !project.isLocked && !['completed', 'archived', 'cancelled', 'cancelled_by_admin', 'deleted_by_owner'].includes(project.status)

  const handleSelectAllProjects = (e) => {
    if (e.target.checked) {
      setSelectedProjects(projectsData.map((project) => project.id))
      return
    }

    setSelectedProjects([])
  }

  const handleSelectProject = (projectId) => {
    setSelectedProjects((prev) => {
      if (prev.includes(projectId)) {
        return prev.filter((id) => id !== projectId)
      }

      return [...prev, projectId]
    })
  }

  const handleBulkRenewDeadlines = async () => {
    const selectedProjectRecords = projectsData.filter((project) => selectedProjects.includes(project.id))
    const eligibleProjects = selectedProjectRecords.filter(isProjectEligibleForRenewal)

    if (!bulkRenewalDate) {
      toast.warning('Please choose a renewal date first')
      return
    }

    if (eligibleProjects.length === 0) {
      toast.warning('No eligible selected projects can be renewed')
      return
    }

    const confirmed = window.confirm(`Renew ${eligibleProjects.length} selected project deadline${eligibleProjects.length === 1 ? '' : 's'} to ${bulkRenewalDate}?`)
    if (!confirmed) return

    try {
      const response = await bulkRenewProjectDeadlinesAsAdmin(
        eligibleProjects.map((project) => project.id),
        bulkRenewalDate
      )

      await fetchProjects()
      setSelectedProjects([])
      setBulkRenewalDate('')
      toast.success(response?.message || 'Project deadlines renewed successfully')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to renew selected project deadlines')
    }
  }

  const openQuickRenewProject = (project) => {
    const today = new Date().toISOString().split('T')[0]
    const initialDate = project.deadline && project.deadline >= today ? project.deadline : today

    setQuickRenewProjectId(project.id)
    setQuickRenewalDate(initialDate)
  }

  const closeQuickRenewProject = () => {
    setQuickRenewProjectId(null)
    setQuickRenewalDate('')
  }

  const handleQuickRenewProject = async (project) => {
    if (!isProjectEligibleForRenewal(project)) {
      toast.warning('This project cannot be renewed')
      return
    }

    if (!quickRenewalDate) {
      toast.warning('Please choose a renewal date')
      return
    }

    const confirmed = window.confirm(`Renew "${project.name}" to ${quickRenewalDate}?`)
    if (!confirmed) return

    try {
      const response = await bulkRenewProjectDeadlinesAsAdmin([project.id], quickRenewalDate)
      await fetchProjects()
      closeQuickRenewProject()
      toast.success(response?.message || 'Project deadline renewed successfully')
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to renew project deadline')
    }
  }

  const BulkProjectActions = () => {
    if (selectedProjects.length === 0 || !canUpdateProjects) return null

    const selectedProjectRecords = projectsData.filter((project) => selectedProjects.includes(project.id))
    const eligibleRenewalProjects = selectedProjectRecords.filter(isProjectEligibleForRenewal)
    const ineligibleRenewalCount = selectedProjectRecords.length - eligibleRenewalProjects.length

    return (
      <div className='bg-white dark:bg-gray-800 p-4 mb-4 rounded-lg shadow-sm space-y-3'>
        <div className='text-sm text-gray-700 dark:text-gray-300'>
          {selectedProjects.length} projects selected
          {' ΓÇó '}
          {eligibleRenewalProjects.length} eligible for renewal
          {ineligibleRenewalCount > 0 && ` ΓÇó ${ineligibleRenewalCount} locked or finalized`}
        </div>

        <div className='flex flex-wrap items-end gap-3'>
          <label className='flex flex-col gap-1 text-sm text-gray-600 dark:text-gray-300'>
            <span>Renew selected projects to</span>
            <input
              type='date'
              value={bulkRenewalDate}
              min={new Date().toISOString().split('T')[0]}
              onChange={(e) => setBulkRenewalDate(e.target.value)}
              className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            />
          </label>

          <button
            type='button'
            onClick={handleBulkRenewDeadlines}
            disabled={eligibleRenewalProjects.length === 0 || !bulkRenewalDate}
            className={`inline-flex items-center gap-2 px-4 py-2 text-sm rounded-md whitespace-nowrap ${
              eligibleRenewalProjects.length === 0 || !bulkRenewalDate ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-cyan-100 text-cyan-800 hover:bg-cyan-200'
            }`}>
            <FaCalendarAlt className='shrink-0' />
            <span>Renew Selected ({eligibleRenewalProjects.length})</span>
          </button>

          <button
            type='button'
            onClick={() => {
              setSelectedProjects([])
              setBulkRenewalDate('')
            }}
            className='inline-flex items-center gap-2 px-4 py-2 text-sm rounded-md whitespace-nowrap bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600'>
            Clear Selection
          </button>
        </div>

        <div className='text-xs text-gray-600 dark:text-gray-300'>Single-project renewal is still available through Edit Project.</div>
      </div>
    )
  }

  const showingFrom = totalFilteredCount === 0 ? 0 : (currentPage - 1) * pageSize + 1
  const showingTo = Math.min(currentPage * pageSize, totalFilteredCount)

  const summaryChips = [
    { key: 'total', label: 'Total', className: 'bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-200' },
    { key: 'active', label: 'Active', className: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300' },
    { key: 'in_progress', label: 'In Progress', className: 'bg-cyan-100 text-cyan-800 dark:bg-cyan-900 dark:text-cyan-300' },
    { key: 'under_review', label: 'Under Review', className: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300' },
    { key: 'completed', label: 'Completed', className: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300' },
    { key: 'cancelled', label: 'Cancelled', className: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300' }
  ]

  const buildProjectsPresetLabel = (filters = {}) => {
    if (filters.stalled === 'true') return 'Queue preset: Stalled projects'
    return ''
  }

  const clearAllFilters = () => {
    setSelectedStatus('All')
    setSelectedCategory('All')
    setPriority('All')
    setDateRange({ start: '', end: '' })
    setStalledOnly(false)
    setSearchQuery('')
    setSortBy('createdAt:desc')
    setCurrentPage(1)
    setActivePresetLabel('')
  }

  useEffect(() => {
    setCurrentPage(1)
  }, [selectedStatus, selectedCategory, selectedPriority, dateRange.start, dateRange.end, stalledOnly, searchQuery, sortBy, pageSize])

  useEffect(() => {
    if (!navigationRequest || navigationRequest.section !== 'projects') return

    const filters = navigationRequest.filters || {}

    setSearchQuery(filters.search || '')
    setSelectedStatus(filters.status || 'All')
    setSelectedCategory(filters.category || 'All')
    setPriority(filters.priority || 'All')
    setDateRange({ start: '', end: '' })
    setStalledOnly(filters.stalled === 'true')
    setSortBy(filters.sort || 'createdAt:desc')
    setCurrentPage(1)
    setActivePresetLabel(buildProjectsPresetLabel(filters))
  }, [navigationRequest?.requestId, navigationRequest?.section])

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages)
    }
  }, [currentPage, totalPages])

  useEffect(() => {
    setSelectedProjects((prev) => prev.filter((projectId) => projectsData.some((project) => project.id === projectId)))
  }, [projectsData])

  useEffect(() => {
    fetchProjects()
  }, [currentPage, pageSize, selectedStatus, selectedCategory, selectedPriority, dateRange.start, dateRange.end, stalledOnly, searchQuery, sortBy])

  return (
    <div>
      <div className='flex justify-between items-center mb-4'>
        <div className='flex flex-col'>
          <h2 className='text-xl font-semibold text-gray-900 dark:text-white'>Projects Overview</h2>
          <div className='mb-2 mt-4 flex flex-wrap gap-2'>
            {summaryChips.map((chip) => (
              <span key={chip.key} className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-semibold ${chip.className}`}>
                {chip.label}
                <span className='opacity-80'>{summaryCounts[chip.key]}</span>
              </span>
            ))}
          </div>
          <div className='text-sm text-gray-600 dark:text-gray-300 mt-1'>
            Showing {showingFrom}-{showingTo} of {totalFilteredCount} {totalFilteredCount === 1 ? 'project' : 'projects'}
            {totalFilteredCount !== overallTotalCount && ` (${overallTotalCount} total)`}
          </div>
        </div>
        {canCreateProjects && (
          <button onClick={() => setIsNewProjectModalOpen(true)} className='flex items-center gap-2 px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90'>
            <FaPlus className='w-4 h-4' />
            New Project
          </button>
        )}
      </div>

      {activePresetLabel && (
        <div className='mb-4 flex flex-wrap items-center justify-between gap-3 rounded-lg border border-accent/20 bg-accent/10 px-4 py-3 text-sm text-gray-800 dark:text-gray-100'>
          <div className='flex items-center gap-2'>
            <span className='inline-flex rounded-full bg-accent px-2.5 py-1 text-xs font-semibold text-white'>Active Queue Preset</span>
            <span>{activePresetLabel}</span>
          </div>

          <button type='button' onClick={clearAllFilters} className='rounded-lg border border-accent/30 bg-white px-3 py-2 text-sm font-medium text-accent hover:bg-accent/5 dark:bg-gray-800 dark:hover:bg-accent/10'>
            Clear preset
          </button>
        </div>
      )}

      <BulkProjectActions />

      {canCreateProjects && <ProjectModal isOpen={isNewProjectModalOpen} onClose={() => setIsNewProjectModalOpen(false)} onProjectCreated={fetchProjects} mode='create' />}

      {/* Search and Filter Bar */}
      <div className='mb-6 bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm'>
        <div className='flex gap-4'>
          <div className='flex-1 relative'>
            <input
              type='text'
              placeholder='Search projects...'
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className='w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            />
            <FaSearch className='absolute left-3 top-3 text-gray-400' />
          </div>
          <select
            value={selectedStatus}
            onChange={(e) => setSelectedStatus(e.target.value)}
            className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            title='Filter by project status'>
            {statusOptions.map((status) => (
              <option key={status} value={status}>
                {status === 'All' ? 'All Statuses' : formatProjectStatusLabel(status)}
              </option>
            ))}
          </select>
          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            title='Filter by category'>
            {categoryOptions.map((category) => (
              <option key={category} value={category}>
                {category === 'All' ? 'All Categories' : category}
              </option>
            ))}
          </select>
          <select
            value={selectedPriority}
            onChange={(e) => setPriority(e.target.value)}
            className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            title='Filter by priority'>
            {priorityOptions.map((priority) => (
              <option key={priority} value={priority}>
                {priority === 'All' ? 'All Priorities' : priority}
              </option>
            ))}
          </select>
          <div className='flex gap-2'>
            <input
              type='date'
              value={dateRange.start}
              onChange={(e) => setDateRange((prev) => ({ ...prev, start: e.target.value }))}
              className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            />
            <input
              type='date'
              value={dateRange.end}
              onChange={(e) => setDateRange((prev) => ({ ...prev, end: e.target.value }))}
              className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            />
            <label className='flex items-center gap-2 px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg dark:bg-gray-700'>
              <input type='checkbox' checked={stalledOnly} onChange={(e) => setStalledOnly(e.target.checked)} className='rounded border-gray-300 text-accent focus:ring-accent' />
              <span className='text-sm theme-text dark:text-gray-200'>Stalled only</span>
            </label>
          </div>
          <button onClick={clearFilters} className='flex items-center gap-2 px-4 py-2 text-sm bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 dark:bg-gray-700 dark:text-gray-300 dark:hover:bg-gray-600'>
            <FaFilter className='w-4 h-4' />
            Clear Filters
          </button>
        </div>
      </div>

      {/* Sort + Pagination Controls */}
      <div className='flex flex-wrap justify-between items-center gap-3 mb-4'>
        <div className='flex items-center gap-3 text-sm text-gray-600 dark:text-gray-300'>
          {canUpdateProjects && (
            <>
              <label className='inline-flex items-center gap-2'>
                <input
                  type='checkbox'
                  onChange={handleSelectAllProjects}
                  checked={projectsData.length > 0 && selectedProjects.length === projectsData.length}
                  className='rounded border-gray-300 text-accent focus:ring-accent'
                />
                <span>Select all on page</span>
              </label>

              {selectedProjects.length > 0 && <span className='text-gray-600 dark:text-gray-300'>{selectedProjects.length} selected</span>}
            </>
          )}
        </div>

        <div className='flex flex-wrap items-center gap-3'>
          <div className='flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300'>
            <span>Show</span>
            <select
              value={pageSize}
              onChange={(e) => setPageSize(Number(e.target.value))}
              className='px-3 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
              title='Projects per page'>
              <option value={30}>30</option>
              <option value={60}>60</option>
              <option value={90}>90</option>
            </select>
          </div>

          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className='px-4 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value='createdAt:desc'>Created (Newest first)</option>
            <option value='createdAt:asc'>Created (Oldest first)</option>
            <option value='deadline:asc'>Deadline (Oldest first)</option>
            <option value='deadline:desc'>Deadline (Newest first)</option>
            <option value='progress:asc'>Progress (Low to High)</option>
            <option value='progress:desc'>Progress (High to Low)</option>
            <option value='priority:asc'>Priority (Low to High)</option>
            <option value='priority:desc'>Priority (High to Low)</option>
          </select>
        </div>
      </div>

      <div className='mb-4 rounded-lg bg-white dark:bg-gray-800 p-4 text-sm text-gray-600 dark:text-gray-300'>Loading projects...</div>
      {error && <div className='mb-4 rounded-lg bg-red-50 dark:bg-red-900/20 p-4 text-sm text-red-600 dark:text-red-300'>{error}</div>}
      {/* Projects Grid */}
      <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6'>
        {/* Project Card */}
        {projectsData.map((project) => {
          const isAdminCancelled = project.status === 'cancelled_by_admin'
          const isProjectLocked = Boolean(project.isLocked)

          return (
            <div
              key={project.id}
              className={`bg-white dark:bg-gray-800 rounded-lg shadow-sm p-6 mb-4 h-full flex flex-col border-2 ${
                selectedProjects.includes(project.id) ? 'border-accent/60 ring-1 ring-accent/20' : 'border-transparent'
              }`}>
              <div className='flex justify-between items-start gap-3 mb-4'>
                <div className='flex items-start gap-3'>
                  {canUpdateProjects && (
                    <input
                      type='checkbox'
                      checked={selectedProjects.includes(project.id)}
                      onChange={() => handleSelectProject(project.id)}
                      className='mt-1 rounded border-gray-300 text-accent focus:ring-accent'
                      title='Select project'
                    />
                  )}
                  <h3 className='font-semibold text-gray-900 dark:text-white'>{project.name}</h3>
                </div>
                <ProjectStatusBadge status={project.status} size='sm' />
              </div>

              <p className='text-sm text-gray-600 dark:text-gray-300 mb-4 line-clamp-3'>{project.description?.length > 180 ? `${project.description.slice(0, 180)}...` : project.description}</p>

              <div className='mt-auto space-y-2'>
                <div className='flex justify-between items-center text-sm text-gray-600 dark:text-gray-300'>
                  <span>Deadline: {project.deadline}</span>
                  <span>Progress: {project.progress}%</span>
                </div>
                <ProgressBar progress={project.progress} />
                <div className='flex justify-between items-center text-sm text-gray-600 dark:text-gray-300'>
                  <PriorityBadge priority={project.priority} size='sm' />
                  <TeamAvatars team={project.team} />
                </div>
              </div>
              <div className='mt-4 pt-4 border-t border-gray-100 dark:border-gray-700 flex justify-end space-x-3'>
                <button onClick={() => openDetailModal(project)} title='Quick details' className='text-gray-600 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white'>
                  <FaEye className='w-4 h-4' />
                </button>

                {canUpdateProjects && (
                  <button
                    onClick={() => openEditModal(project)}
                    disabled={isAdminCancelled}
                    title={isAdminCancelled ? 'Project was canceled by admin. Editing is disabled.' : 'Edit project'}
                    className={`${isAdminCancelled ? 'text-gray-400 cursor-not-allowed' : 'text-blue-600 hover:text-blue-900 dark:text-blue-400 dark:hover:text-blue-200'}`}>
                    <FaEdit className='w-4 h-4' />
                  </button>
                )}

                {canUpdateProjects && (
                  <button
                    onClick={() => openQuickRenewProject(project)}
                    disabled={!isProjectEligibleForRenewal(project)}
                    title={!isProjectEligibleForRenewal(project) ? 'Locked or finalized projects cannot be renewed.' : 'Quick renew deadline'}
                    className={`${!isProjectEligibleForRenewal(project) ? 'text-gray-400 cursor-not-allowed' : 'text-cyan-600 hover:text-cyan-900 dark:text-cyan-400 dark:hover:text-cyan-200'}`}>
                    <FaCalendarAlt className='w-4 h-4' />
                  </button>
                )}

                {canLockProjects && (
                  <button
                    onClick={() => handleToggleProjectLock(project)}
                    disabled={isAdminCancelled || lockLoadingProjectId === project.id}
                    title={isAdminCancelled ? 'Project was canceled by admin. Status changes are disabled.' : isProjectLocked ? 'Unlock project' : 'Lock / Pause project'}
                    className={`${
                      isAdminCancelled || lockLoadingProjectId === project.id
                        ? 'text-gray-400 cursor-not-allowed'
                        : isProjectLocked
                          ? 'text-red-800 hover:text-red-900 dark:text-red-500 dark:hover:text-red-400'
                          : 'text-yellow-600 hover:text-yellow-900 dark:text-yellow-400 dark:hover:text-yellow-200'
                    }`}>
                    <FaLock className='w-4 h-4' />
                  </button>
                )}

                {canDeleteProjects && (
                  <button
                    onClick={() => openDeleteModal(project)}
                    disabled={isAdminCancelled}
                    title={isAdminCancelled ? 'Project already canceled by admin.' : 'Cancel project as admin'}
                    className={`${isAdminCancelled ? 'text-gray-400 cursor-not-allowed' : 'text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-200'}`}>
                    <FaTrash className='w-4 h-4' />
                  </button>
                )}
              </div>

              {quickRenewProjectId === project.id && (
                <div className='mt-4 rounded-md border border-cyan-200 dark:border-cyan-900/40 bg-cyan-50 dark:bg-cyan-900/20 p-3 space-y-3'>
                  <div className='text-sm font-medium text-cyan-900 dark:text-cyan-200'>Quick Renew Deadline</div>

                  <div className='flex flex-wrap items-end gap-3'>
                    <label className='flex flex-col gap-1 text-sm text-cyan-900 dark:text-cyan-200'>
                      <span>New deadline</span>
                      <input
                        type='date'
                        value={quickRenewalDate}
                        min={new Date().toISOString().split('T')[0]}
                        onChange={(e) => setQuickRenewalDate(e.target.value)}
                        className='px-3 py-2 border border-cyan-200 dark:border-cyan-800 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent bg-white dark:bg-gray-800 dark:text-white'
                      />
                    </label>

                    <button
                      type='button'
                      onClick={() => handleQuickRenewProject(project)}
                      disabled={!quickRenewalDate}
                      className={`inline-flex items-center gap-2 px-4 py-2 text-sm rounded-md whitespace-nowrap ${
                        !quickRenewalDate ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-cyan-100 text-cyan-800 hover:bg-cyan-200'
                      }`}>
                      <FaCalendarAlt className='shrink-0' />
                      <span>Save Renewal</span>
                    </button>

                    <button
                      type='button'
                      onClick={closeQuickRenewProject}
                      className='inline-flex items-center gap-2 px-4 py-2 text-sm rounded-md whitespace-nowrap bg-white text-gray-700 hover:bg-gray-100 dark:bg-gray-700 dark:text-gray-200 dark:hover:bg-gray-600'>
                      Cancel
                    </button>
                  </div>
                </div>
              )}

              {project.isLocked && (
                <div className='mt-4 rounded-md border border-red-200 dark:border-red-900/40 bg-red-50 dark:bg-red-900/20 p-3 text-xs text-red-700 dark:text-red-300'>
                  <div>
                    <span className='font-semibold'>Lock reason:</span> {project.lockReason || 'Not specified'}
                  </div>
                  <div>
                    <span className='font-semibold'>Unlocks:</span> {project.lockExpiresAt ? new Date(project.lockExpiresAt).toLocaleString() : 'No end date'}
                  </div>
                </div>
              )}
            </div>
          )
        })}
      </div>

      {totalFilteredCount > 0 && (
        <PaginationControls currentPage={currentPage} totalPages={totalPages} onPrev={() => setCurrentPage((prev) => Math.max(1, prev - 1))} onNext={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))} />
      )}
      <AdminProjectDetailModal isOpen={isDetailModalOpen} onClose={closeDetailModal} project={projectForDetails} />
      <AdminProjectEditModal
        isOpen={isEditModalOpen}
        onClose={closeEditModal}
        onSave={handleEditProject}
        loading={editLoading}
        form={editForm}
        setForm={setEditForm}
        assigneeName={editingProjectMeta?.assignee ? `${editingProjectMeta.assignee.firstName || ''} ${editingProjectMeta.assignee.lastName || ''}`.trim() : ''}
        ownerName={editingProjectMeta?.owner ? `${editingProjectMeta.owner.firstName || ''} ${editingProjectMeta.owner.lastName || ''}`.trim() : ''}
        canRemoveAssignee={Boolean(editingProjectMeta?.assignee)}
        onRemoveAssignee={handleRemoveAssigneeFromEditModal}
        removeAssigneeLoading={removeAssigneeLoading}
      />
      <AdminProjectCancelModal isOpen={isDeleteModalOpen} onClose={closeDeleteModal} onConfirm={handleDeleteProject} projectName={projectToDelete?.name} loading={deleteLoading} />
      <AdminLockProjectModal isOpen={isLockModalOpen} onClose={closeLockModal} onConfirm={handleConfirmLockProject} project={projectToLock} loading={lockLoadingProjectId === projectToLock?.id} />
    </div>
  )
}

AdminProjectsList.propTypes = {
  navigationRequest: PropTypes.shape({})
}

export default AdminProjectsList

import { useState, useEffect } from 'react'
import PropTypes from 'prop-types'
import { getAdminDashboardStats } from '../../services/userService'
import AdminAlertsPanel from './AdminAlertsPanel'
import AdminAuditLogPanel from './AdminAuditLogPanel'
import StatCard from './StatCard'
import { FaUsers, FaProjectDiagram, FaCheckCircle, FaMoneyBillWave, FaUserCheck, FaDollarSign, FaBullseye, FaLayerGroup, FaChartLine } from 'react-icons/fa'

const defaultStats = {
  totalUsers: 0,
  activeProjects: 0,
  completedProjects: 0,
  revenue: 0,
  comparisons: {
    users: 0,
    activeProjects: 0,
    completedProjects: 0,
    revenue: 0
  },
  alertSummary: {
    total: 0,
    critical: 0,
    warning: 0,
    info: 0
  },
  alerts: [],
  healthSignals: {
    lockedUsers: 0,
    inactiveUsers: 0,
    unverifiedUsers: 0,
    passwordResetRequiredUsers: 0,
    stalledProjects: 0
  },
  kpis: {
    activeUserRate: 0,
    avgCompletedProjectValue: 0,
    completionRate: 0,
    newProjectsLast30: 0,
    newProjectsTrend: 0
  }
}

const AdminStats = ({ onOpenSection }) => {
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState('')
  const [stats, setStats] = useState(defaultStats)

  useEffect(() => {
    fetchDashboardStats()
  }, [])

  const fetchDashboardStats = async () => {
    setIsLoading(true)
    setError('')

    try {
      const data = await getAdminDashboardStats()

      setStats({
        ...defaultStats,
        ...data,
        comparisons: {
          ...defaultStats.comparisons,
          ...(data?.comparisons || {})
        },
        alertSummary: {
          ...defaultStats.alertSummary,
          ...(data?.alertSummary || {})
        },
        healthSignals: {
          ...defaultStats.healthSignals,
          ...(data?.healthSignals || {})
        },
        kpis: {
          ...defaultStats.kpis,
          ...(data?.kpis || {})
        },
        alerts: Array.isArray(data?.alerts) ? data.alerts : []
      })
    } catch (err) {
      console.error('Error fetching dashboard stats:', err)
      setError(err.response?.data?.message || 'Failed to load dashboard stats.')
    } finally {
      setIsLoading(false)
    }
  }

  const statCards = [
    {
      title: 'Total Users',
      value: isLoading ? '...' : stats.totalUsers.toLocaleString(),
      icon: <FaUsers />,
      trend: stats.comparisons.users
    },
    {
      title: 'Active Projects',
      value: isLoading ? '...' : stats.activeProjects.toLocaleString(),
      icon: <FaProjectDiagram />,
      trend: stats.comparisons.activeProjects
    },
    {
      title: 'Completed Projects',
      value: isLoading ? '...' : stats.completedProjects.toLocaleString(),
      icon: <FaCheckCircle />,
      trend: stats.comparisons.completedProjects
    },
    {
      title: 'Revenue',
      value: isLoading ? '...' : `$${stats.revenue.toLocaleString()}`,
      icon: <FaMoneyBillWave />,
      trend: stats.comparisons.revenue
    }
  ]

  const kpiCards = [
    {
      title: 'Active User Rate',
      value: isLoading ? '...' : `${stats.kpis?.activeUserRate ?? 0}%`,
      icon: <FaUserCheck />
    },
    {
      title: 'Avg Completed Value',
      value: isLoading ? '...' : `$${(stats.kpis?.avgCompletedProjectValue ?? 0).toLocaleString()}`,
      icon: <FaDollarSign />
    },
    {
      title: 'Completion Rate',
      value: isLoading ? '...' : `${stats.kpis?.completionRate ?? 0}%`,
      icon: <FaBullseye />
    },
    {
      title: 'New Projects (30d)',
      value: isLoading ? '...' : (stats.kpis?.newProjectsLast30 ?? 0).toLocaleString(),
      icon: <FaLayerGroup />,
      trend: stats.kpis?.newProjectsTrend ?? 0
    }
  ]

  return (
    <div>
      <div className='flex items-center justify-between mb-6'>
        <div>
          <h2 className='text-2xl font-bold text-gray-900 dark:text-white'>Dashboard Overview</h2>
          <p className='text-sm text-gray-500 dark:text-gray-400 mt-1'>Metrics comparison: Current 30 days vs Previous 30 days</p>
        </div>
        <button onClick={fetchDashboardStats} className='px-4 py-2 bg-accent text-white rounded-lg hover:bg-accent/90 transition-all text-sm font-medium'>
          Refresh Stats
        </button>
      </div>

      {error && <div className='mb-6 rounded-xl border border-red-200 dark:border-red-900/40 bg-red-50 dark:bg-red-900/20 px-4 py-3 text-sm text-red-700 dark:text-red-300'>{error}</div>}

      <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6'>
        {statCards.map((stat, index) => (
          <StatCard key={index} {...stat} isLoading={isLoading} />
        ))}
      </div>

      <div className='mt-8'>
        <div className='flex items-center gap-2 mb-4'>
          <FaChartLine className='text-accent' />
          <h3 className='text-lg font-semibold text-gray-900 dark:text-white'>Advanced KPI Metrics</h3>
        </div>
        <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6'>
          {kpiCards.map((stat, index) => (
            <StatCard key={`kpi-${index}`} {...stat} isLoading={isLoading} />
          ))}
        </div>
      </div>

      <AdminAlertsPanel isLoading={isLoading} alertSummary={stats.alertSummary} alerts={stats.alerts} healthSignals={stats.healthSignals} onOpenSection={onOpenSection} />
      <AdminAuditLogPanel />
    </div>
  )
}

AdminStats.propTypes = {
  onOpenSection: PropTypes.func.isRequired
}

export default AdminStats

import { FaTrash, FaLock, FaEnvelope, FaUserCog, FaSearch, FaFileExport, FaKey, FaCheckCircle, FaClock } from 'react-icons/fa'
import PropTypes from 'prop-types'
import { useState, useEffect, useRef } from 'react'
import { getAdminUsers, toggleUserLock, updateAdminUser, requestAdminPasswordReset, requestAdminEmailVerification, reactivateAdminUser, verifyAdminUserDirect, deleteAdminUser } from '../../services/userService'
import AdminUserEditModal from '../../modal/AdminUserEditModal'
