    setIsEditModalOpen(true)
  }

  const closeEditModal = () => {
    setIsEditModalOpen(false)
    setEditingUser(null)
  }

  const handleSaveUser = async (payload) => {
    try {
      await updateAdminUser(payload._id, payload)
      await fetchUsers()
      closeEditModal()
    } catch (error) {
      alert(error.response?.data?.message || 'Failed to update user')
    }
  }

  // Export to CSV
  const exportToCSV = () => {
    const headers = ['Verification', 'Name', 'Email', 'Role', 'Status', 'Subscription', 'Join Date']

    const escapeCSV = (value) => `"${String(value ?? '').replace(/"/g, '""')}"`

    const data = users.map((user) => [
      user.isEmailVerified ? 'Verified' : 'Pending',
      `${user.firstName || ''} ${user.lastName || ''}`.trim(),
      user.email || '',
      user.userType || '',
      getUserStatus(user),
      user.subscription?.type || 'N/A',
      user.createdAt ? new Date(user.createdAt).toLocaleDateString() : ''
    ])

    const csvContent = [headers.map(escapeCSV).join(','), ...data.map((row) => row.map(escapeCSV).join(','))].join('\n')

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const link = document.createElement('a')
    const url = URL.createObjectURL(blob)

    link.setAttribute('href', url)
    link.setAttribute('download', 'users_export.csv')
    link.style.visibility = 'hidden'
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  return (
    <div>
      <h2 className='text-xl font-semibold mb-4 text-gray-900 dark:text-white'>Users Management</h2>
      <BulkActions />
      {/* Filters Section */}

      <div className='mb-4 flex items-center justify-between bg-white dark:bg-gray-800 p-4 rounded-lg shadow-sm'>
        <div className='flex items-center gap-4'>
          <div className='text-sm'>
            <span className='text-gray-500 dark:text-gray-400'>Total Users: </span>
            <span className='font-semibold text-gray-900 dark:text-white'>{total}</span>
          </div>
          <div className='text-sm'>
            <span className='text-gray-500 dark:text-gray-400'>Showing: </span>
            <span className='font-semibold text-gray-900 dark:text-white'>{users.length}</span>
          </div>
        </div>
        <button
          onClick={exportToCSV}
          className='flex items-center gap-2 px-4 py-2 text-sm bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition-colors'>
          <FaFileExport className='w-4 h-4' />
          Export CSV
        </button>
      </div>

      {activePresetLabel && (
        <div className='mb-4 flex flex-wrap items-center justify-between gap-3 rounded-lg border border-accent/20 bg-accent/10 px-4 py-3 text-sm text-gray-800 dark:text-gray-100'>
          <div className='flex items-center gap-2'>
            <span className='inline-flex rounded-full bg-accent px-2.5 py-1 text-xs font-semibold text-white'>Active Queue Preset</span>
            <span>{activePresetLabel}</span>
          </div>

          <button type='button' onClick={clearAllFilters} className='rounded-lg border border-accent/30 bg-white px-3 py-2 text-sm font-medium text-accent hover:bg-accent/5 dark:bg-gray-800 dark:hover:bg-accent/10'>
            Clear preset
          </button>
        </div>
      )}

      <div className='mb-6 bg-white dark:bg-gray-800 rounded-lg p-4 shadow-sm space-y-4'>
        {/* Search Row */}
        <div className='w-full'>
          <div className='relative'>
            <input
              type='text'
              placeholder='Search users by name or email...'
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className='w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
            />
            <FaSearch className='absolute left-3 top-3 text-gray-400' />
          </div>
        </div>

        {/* Filters Row */}
        <div className='flex flex-wrap gap-3 w-full'>
          <select
            value={selectedRole}
            onChange={(e) => setSelectedRole(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value=''>All Roles</option>
            {roleTypes.map((role) => (
              <option key={role} value={role}>
                {role.charAt(0).toUpperCase() + role.slice(1)}
              </option>
            ))}
          </select>

          <select
            value={selectedStatus}
            onChange={(e) => setSelectedStatus(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value=''>All Status</option>
            {statusTypes.map((status) => (
              <option key={status.value} value={status.value}>
                {status.label}
              </option>
            ))}
          </select>

          <select
            value={selectedVerification}
            onChange={(e) => setSelectedVerification(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value=''>All Verification</option>
            <option value='verified'>Verified</option>
            <option value='unverified'>Unverified</option>
          </select>

          <select
            value={selectedPasswordResetRequired}
            onChange={(e) => setSelectedPasswordResetRequired(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value=''>All Recovery States</option>
            <option value='true'>Password Reset Required</option>
            <option value='false'>No Forced Reset</option>
          </select>

          <input
            type='text'
            value={selectedAdminTag}
            onChange={(e) => setSelectedAdminTag(e.target.value)}
            placeholder='Filter by admin tag...'
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
          />

          <select
            value={selectedNotesState}
            onChange={(e) => setSelectedNotesState(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value=''>All Note States</option>
            <option value='with_notes'>With Internal Notes</option>
            <option value='without_notes'>Without Internal Notes</option>
          </select>

          <select
            value={sortConfig}
            onChange={(e) => setSortConfig(e.target.value)}
            className='flex-1 px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-700 focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'>
            <option value='createdAt:desc'>Newest First</option>
            <option value='createdAt:asc'>Oldest First</option>
            <option value='lastLogin:desc'>Recent Login First</option>
            <option value='lastLogin:asc'>Oldest Login First</option>
            <option value='isEmailVerified:desc'>Verified First</option>
            <option value='isEmailVerified:asc'>Pending First</option>
          </select>

          <div className='flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300'>
            <span>Show</span>
            <select
              value={pageSize}
              onChange={(e) => setPageSize(Number(e.target.value))}
              className='px-3 py-2 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-accent dark:bg-gray-700 dark:text-white'
              title='Users per page'>
              <option value={10}>10</option>
              <option value={30}>30</option>
              <option value={60}>60</option>
              <option value={90}>90</option>
            </select>
          </div>

          <button
            onClick={() => {
              clearAllFilters()
            }}
            className='px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors'>
            Reset
          </button>
        </div>
      </div>

      {/* User Table */}
      <div className='overflow-x-auto'>
        <div className='min-w-[800px] sm:w-full p-4 sm:p-0'>
          <table className='min-w-full bg-white dark:bg-gray-800 rounded-lg'>
            <thead>
              <tr className='bg-gray-50 dark:bg-gray-700'>
                <th className='px-6 py-3 w-4 text-center'>
                  <input type='checkbox' onChange={handleSelectAll} checked={users.length > 0 && selectedUsers.length === users.length} className='rounded border-gray-300 text-accent focus:ring-accent' />
                </th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>
                  <button type='button' onClick={toggleVerificationSort} className='inline-flex items-center gap-2 hover:text-accent transition-colors' title={verificationSortLabel}>
                    <span>Verification</span>
                  </button>
                </th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Name</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Email</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Role</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Status</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Join Date</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Last Login</th>
                <th className='px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider'>Actions</th>
              </tr>
            </thead>
            <tbody className='divide-y divide-gray-200 dark:divide-gray-700'>
              {loading ? (
                <tr>
                  <td colSpan='9' className='px-6 py-4 text-center text-gray-500'>
                    Loading users...
                  </td>
                </tr>
              ) : error ? (
                <tr>
                  <td colSpan='9' className='px-6 py-4 text-center text-red-500'>
                    {error}
                  </td>
                </tr>
              ) : users.length === 0 ? (
                <tr>
                  <td colSpan='9' className='px-6 py-4 text-center text-gray-500'>
                    No users found
                  </td>
                </tr>
              ) : (
                users.map((user) => (
                  <tr key={user._id}>
                    <td className='px-6 py-4 w-4 text-center'>
                      <input type='checkbox' checked={selectedUsers.includes(user._id)} onChange={() => handleSelectUser(user._id)} className='rounded border-gray-300 text-accent focus:ring-accent' />
                    </td>
                    <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>
                      {(() => {
                        const verification = getVerificationMeta(user)
                        return (
                          <div className='flex items-center gap-2' title={verification.label}>
                            {verification.icon}
                            <span className='hidden sm:inline'>{verification.label}</span>
                          </div>
                        )
                      })()}
                    </td>
                    <td className='px-6 py-4 text-sm text-gray-900 dark:text-gray-100 cursor-pointer' onClick={() => openDetailsModal(user)}>
                      <div className='space-y-2'>
                        <div className='font-medium'>
                          {user.firstName} {user.lastName}
                        </div>

                        {Array.isArray(user.adminTags) && user.adminTags.length > 0 && (
                          <div className='flex flex-wrap gap-2'>
                            {user.adminTags.slice(0, 2).map((tag) => (
                              <span key={`${user._id}-${tag}`} className='inline-flex items-center rounded-full bg-amber-100 px-2.5 py-1 text-xs font-medium text-amber-800 dark:bg-amber-900/30 dark:text-amber-300'>
                                {tag}
                              </span>
                            ))}

                            {user.adminTags.length > 2 && (
                              <span className='inline-flex items-center rounded-full bg-gray-100 px-2.5 py-1 text-xs font-medium text-gray-600 dark:bg-gray-700 dark:text-gray-300'>+{user.adminTags.length - 2} more</span>
                            )}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className='px-6 py-4 text-sm text-gray-500 dark:text-gray-400'>
                      <div className='space-y-2'>
                        <div className='break-all'>{user.email}</div>

                        {hasAdminNotes(user) && (
                          <span className='inline-flex items-center rounded-full bg-blue-100 px-2.5 py-1 text-xs font-medium text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'>Has internal note</span>
                        )}
                      </div>
                    </td>
                    <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>{user.userType.charAt(0).toUpperCase() + user.userType.slice(1)}</td>
                    <td className='px-6 py-4 whitespace-nowrap'>
                      {(() => {
                        const status = getUserStatus(user)
                        return <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${getStatusBadgeClasses(status)}`}>{status}</span>
                      })()}
                    </td>
                    <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>{new Date(user.createdAt).toLocaleDateString()}</td>
                    <td className='px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400'>{user.lastLogin ? new Date(user.lastLogin).toLocaleDateString() : 'Never'}</td>
                    <td className='px-6 py-4 whitespace-nowrap text-sm font-medium space-x-3 flex'>
                      {canUpdateUsers && (
                        <button className='text-green-600 hover:text-green-900 dark:text-green-400 dark:hover:text-green-200' onClick={() => openEditModal(user)} title='Edit user'>
                          <FaUserCog className='w-4 h-4' />
                        </button>
                      )}

                      {canLockUsers && (
                        <button
                          onClick={() => {
                            if (user.isLocked) {
                              handleLockUser(user)
                            } else {
                              openLockModal(user)
                            }
                          }}
                          title={user.isLocked ? 'Unlock user' : 'Lock user'}
                          className='text-yellow-600 hover:text-yellow-900 dark:text-yellow-400 dark:hover:text-yellow-200'>
                          <FaLock className='w-4 h-4' />
                        </button>
                      )}

                      {canResetUsers && !isPrivilegedUser(user) && (
                        <button onClick={() => handlePasswordReset(user)} title='Send password reset email' className='text-blue-600 hover:text-blue-900 dark:text-blue-400 dark:hover:text-blue-200'>
                          <FaKey className='w-4 h-4' />
                        </button>
                      )}

                      {canUpdateUsers && !isPrivilegedUser(user) && !user.isLocked && getUserStatus(user) === 'Inactive' && (
                        <button onClick={() => handleReactivateUser(user)} title='Reactivate user activity' className='text-cyan-600 hover:text-cyan-900 dark:text-cyan-400 dark:hover:text-cyan-200'>
                          <FaClock className='w-4 h-4' />
                        </button>
                      )}

                      {canVerifyUsers && !user.isEmailVerified && (
                        <>
                          <button onClick={() => handleVerificationResend(user)} title='Send verification email' className='text-amber-600 hover:text-amber-900 dark:text-amber-400 dark:hover:text-amber-200'>
                            <FaEnvelope className='w-4 h-4' />
                          </button>

                          <button onClick={() => handleDirectVerifyUser(user)} title='Directly verify user email' className='text-emerald-600 hover:text-emerald-900 dark:text-emerald-400 dark:hover:text-emerald-200'>
                            <FaCheckCircle className='w-4 h-4' />
                          </button>
                        </>
                      )}

                      <button onClick={() => openMailModal(user)} title='Send admin mail' className='text-purple-600 hover:text-purple-900 dark:text-purple-400 dark:hover:text-purple-200'>
                        <FaEnvelope className='w-4 h-4' />
                      </button>

                      {canDeleteUsers && (
                        <button onClick={() => handleDeleteUser(user)} title='Delete user' className='text-red-600 hover:text-red-900 dark:text-red-400 dark:hover:text-red-200'>
                          <FaTrash className='w-4 h-4' />
                        </button>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
          <PaginationControls currentPage={currentPage} totalPages={totalPages} onPrev={() => setCurrentPage((prev) => Math.max(1, prev - 1))} onNext={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))} />
        </div>
      </div>
      <AdminUserEditModal isOpen={isEditModalOpen} onClose={closeEditModal} user={editingUser} onSave={handleSaveUser} />
      <AdminLockUserModal isOpen={isLockModalOpen} onClose={closeLockModal} onConfirm={handleConfirmLock} user={lockingUser} />
      <AdminLockUserModal isOpen={isBulkLockModalOpen} onClose={closeBulkLockModal} onConfirm={handleConfirmBulkLock} user={bulkLockTarget} />
      <AdminUserDetailsModal isOpen={isDetailsModalOpen} onClose={closeDetailsModal} user={selectedUser} />
      <AdminMailUserModal isOpen={isMailModalOpen} onClose={closeMailModal} recipient={mailRecipient} onSent={fetchUsers} />
    </div>
  )
}

AdminUsersList.propTypes = {
  navigationRequest: PropTypes.shape({})
}

export default AdminUsersList

import { useLocation, useNavigate } from 'react-router-dom'
import { FaCheckCircle, FaClock, FaEuroSign, FaMapMarkerAlt, FaUser } from 'react-icons/fa'
import { motion } from 'framer-motion'
import PropTypes from 'prop-types'
import { useAuth } from '../../context/AuthContext'
import VerificationBadge from '../shared/VerificationBadge'
import SkillsList from '../shared/SkillsList'
import RoleTagBadge from '../shared/RoleTagBadge'

const FreelancerCard = ({ freelancer, index, connectionStatus = 'none' }) => {
  const navigate = useNavigate()
  const location = useLocation()
  const { currentUser } = useAuth()

  const announcement = freelancer
  const freelancerInfo = freelancer.freelancer
  const returnTo = `${location.pathname}${location.search}`

  const truncateText = (text, maxLength = 100) => {
    if (!text) return ''
    return text.length > maxLength ? `${text.substring(0, maxLength)}...` : text
  }

  const roleLabel = freelancerInfo.userType === 'both' ? 'Client & Freelancer' : 'Freelancer'

  const connectionBadge =
    connectionStatus === 'accepted'
      ? {
          label: 'Connected',
          className: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-300 border border-emerald-500/30 dark:border-emerald-500/20'
        }
      : connectionStatus === 'pending'
        ? {
            label: 'Request Sent',
            className: 'bg-orange-500/10 text-orange-600 dark:text-orange-300 border border-orange-500/30 dark:border-orange-500/20'
          }
        : connectionStatus === 'incoming'
          ? {
              label: 'Incoming Request',
              className: 'bg-accent/10 text-accent border border-accent/30 dark:border-accent/20'
            }
          : null

  const quickFacts = [
    {
      key: 'availability',
      icon: <FaClock className='text-[11px]' />,
      label: freelancerInfo.availabilityLabel
    },
    {
      key: 'rate',
      icon: <FaEuroSign className='text-[11px]' />,
      label: freelancerInfo.hourlyRateLabel
    },
    freelancerInfo.location
      ? {
          key: 'location',
          icon: <FaMapMarkerAlt className='text-[11px]' />,
          label: freelancerInfo.location
        }
      : null
  ].filter(Boolean)

  const CardShell = ({ children, locked = false }) => (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={
        locked
          ? undefined
          : {
              scale: 1.02,
              transition: { duration: 0.1 }
            }
      }
      transition={{ duration: 0.2, delay: index * 0.1 }}
      onClick={() => {
        if (locked) {
          navigate('/login')
          return
        }

        navigate(`/freelancer/${freelancerInfo._id}`, {
          state: { returnTo }
        })
      }}
      className={`relative bg-gradient-to-br dark:from-light/10 dark:via-light/5 from-primary/10 via-primary/5 to-transparent backdrop-blur-sm rounded-lg p-6 cursor-pointer transition-all duration-300 hover:shadow-xl hover:bg-accent/5 flex flex-col h-full ${
        locked ? 'opacity-75 hover:opacity-100' : ''
      }`}>
      {children}
    </motion.div>
  )

  const CardContent = ({ blurred = false }) => (
    <div className={`${blurred ? 'opacity-50 pointer-events-none ' : ''}flex flex-col h-full`}>
      <div className='flex items-start gap-4 mb-4'>
        <img src={freelancerInfo.profilePicture || `https://i.pravatar.cc/150?u=${freelancerInfo._id}`} alt={freelancerInfo.name} className='w-14 h-14 rounded-full object-cover flex-shrink-0 border border-accent/20' />

        <div className='flex-1 min-w-0'>
          <div className='flex items-start justify-between gap-3 mb-2'>
            <div className='min-w-0'>
              <h3 className='text-lg font-bold theme-text leading-tight'>{freelancerInfo.name}</h3>
              <p className='text-sm theme-text-secondary mt-1 line-clamp-2'>{freelancerInfo.specialty}</p>
            </div>

            <div className='flex flex-col items-end gap-2 shrink-0'>
              <RoleTagBadge role={roleLabel} size='sm' />
              {connectionBadge && <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[11px] font-medium whitespace-nowrap ${connectionBadge.className}`}>{connectionBadge.label}</span>}
              <VerificationBadge isVerified={freelancerInfo.isEmailVerified} className='whitespace-nowrap px-2.5 py-1' />
            </div>
          </div>
        </div>
      </div>

      {quickFacts.length > 0 && (
        <div className='flex flex-wrap gap-2 mb-4 pb-4 border-b border-accent/20'>
          {quickFacts.map((fact) => (
            <span key={fact.key} className='inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs bg-primary/10 dark:bg-light/10 theme-text-secondary border border-primary/10 dark:border-light/10'>
              {fact.icon}
              <span>{fact.label}</span>
            </span>
          ))}
        </div>
      )}

      <div className='flex-1 mb-4'>
        <div className='bg-accent/10 rounded-lg p-4 border-l-2 border-accent h-full flex flex-col'>
          <p className='text-[11px] uppercase tracking-wide text-accent/80 mb-2'>Current Announcement</p>
          <h4 className='text-sm font-semibold text-accent mb-2 line-clamp-2'>{announcement.title}</h4>
          <p className='text-xs theme-text-secondary line-clamp-3 mb-4 flex-1'>{truncateText(announcement.background, 120)}</p>

          {freelancerInfo.primarySkills && freelancerInfo.primarySkills.length > 0 && <SkillsList skills={freelancerInfo.primarySkills} className='mb-4' />}
        </div>
      </div>

      <div className='mt-auto flex items-center justify-between gap-3 border-t border-accent/20 pt-4'>
        <div className='flex items-center gap-2 theme-text-secondary text-sm'>
          <FaCheckCircle className='text-accent' />
          <span>View Profile</span>
        </div>

        <span className='text-xs theme-text-muted'>{freelancerInfo.yearsOfExperience > 0 ? `Years of experience: ${freelancerInfo.yearsOfExperience}+` : 'Years of experience: N/A'}</span>
      </div>
    </div>
  )

  if (currentUser) {
    return (
      <CardShell>
        <CardContent />
      </CardShell>
    )
  }

  return (
    <CardShell locked>
      <div className='absolute inset-0 bg-black/40 rounded-lg flex items-center justify-center flex-col gap-2 backdrop-blur-sm z-10'>
        <FaUser className='text-accent text-3xl' />
        <span className='text-sm font-semibold text-white text-center px-4'>Login to View Profile</span>
      </div>

      <CardContent blurred />
    </CardShell>
  )
}

FreelancerCard.propTypes = {
  freelancer: PropTypes.shape({
    _id: PropTypes.string,
    userId: PropTypes.shape({
      _id: PropTypes.string,
      firstName: PropTypes.string,
      lastName: PropTypes.string,
      email: PropTypes.string
    }),
    freelancer: PropTypes.shape({
      _id: PropTypes.string,
      userType: PropTypes.string,
      name: PropTypes.string,
      specialty: PropTypes.string,
      profilePicture: PropTypes.string,
      isEmailVerified: PropTypes.bool,
      availabilityLabel: PropTypes.string,
      hourlyRateLabel: PropTypes.string,
      location: PropTypes.string,
      primarySkills: PropTypes.array,
      yearsOfExperience: PropTypes.number
    })
  }).isRequired,
  index: PropTypes.number,
  connectionStatus: PropTypes.string
}

// Inner component props (defined inside FreelancerCard)
// CardShell and CardContent would ideally be extracted to separate components

export default FreelancerCard

import { useState, useEffect, useContext, useRef } from 'react'
import { motion } from 'framer-motion'
import { FaUser, FaBriefcase, FaSearch } from 'react-icons/fa'
import { useLocation, useSearchParams } from 'react-router-dom'
import { SearchContext } from '../../context/SearchContext'
import ProjectCard from './ProjectCard'
import FreelancerCard from './FreelancerCard'
import CardLoader from './CardLoader'
import { getAllProjects, getInterestedProjects } from '../../services/projectService'
import { getAllAnnouncements } from '../../services/announcementService'
import { getFavoriteProjects, addToFavorites, removeFromFavorites, getMyConnections } from '../../services/userService'
import { useAuth } from '../../context/AuthContext'

const parseCommaSeparatedList = (value) => {
  if (!value || typeof value !== 'string') return []

  return value
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean)
}

const formatAvailabilityLabel = (value) => {
  switch (value) {
    case 'available':
      return 'Available'
    case 'limited':
      return 'Limited availability'
    case 'unavailable':
      return 'Unavailable'
    default:
      return 'Availability not specified'
  }
}

const buildFreelancerListingModel = (announcement) => {
  const user = announcement.userId || {}
  const name = [user.firstName, user.lastName].filter(Boolean).join(' ').trim() || 'Freelancer'

  const fallbackSkills = parseCommaSeparatedList(user.skills)
  const fallbackCategories = parseCommaSeparatedList(user.serviceCategories)
  const primarySkills = (announcement.skills && announcement.skills.length > 0 ? announcement.skills : [...fallbackSkills, ...fallbackCategories]).slice(0, 4)

  const specialty = user.headline?.trim() || fallbackCategories[0] || 'Freelancer available for project work'
  const publicLocation = user.showLocationPublic && user.location ? user.location : ''
  const effectiveHourlyRate = user.showHourlyRate ? (user.hourlyRate ?? announcement.hourlyRate ?? null) : null

  return {
    _id: announcement._id,
    title: announcement.title,
    background: announcement.background,
    hourlyRate: announcement.hourlyRate,
    skills: announcement.skills,
    isActive: announcement.isActive,
    name,
    specialty,
    searchText: [name, specialty, announcement.title, announcement.background, ...primarySkills].filter(Boolean).join(' ').toLowerCase(),
    freelancer: {
      _id: user._id,
      firstName: user.firstName || '',
      lastName: user.lastName || '',
      name,
      specialty,
      profilePicture: user.profilePicture || '',
      userType: user.userType,
      headline: user.headline || '',
      availabilityStatus: user.availabilityStatus || 'available',
      availabilityLabel: formatAvailabilityLabel(user.availabilityStatus),
      experienceLevel: user.experienceLevel || 'entry',
      yearsOfExperience: user.yearsOfExperience ?? 0,
      skills: user.skills || '',
      serviceCategories: user.serviceCategories || '',
      primarySkills,
      location: publicLocation,
      timezone: user.timezone || '',
      hourlyRate: effectiveHourlyRate,
      hourlyRateLabel: effectiveHourlyRate !== null ? `Γé¼${effectiveHourlyRate}/hr` : 'Rate on request',
      showHourlyRate: user.showHourlyRate ?? true,
      showLocationPublic: user.showLocationPublic ?? true,
      profileVisibility: user.profileVisibility || 'public',
      isEmailVerified: Boolean(user.isEmailVerified)
    }
  }
}

const normalizeListingTab = (value) => {
  if (value === 'freelancers' || value === 'talent') return 'freelancers'
  if (value === 'projects' || value === 'work') return 'projects'
  return 'projects'
}

const defaultProjectFilters = {
  category: 'all',
  priority: 'all',
  budget: 'all',
  applied: 'all'
}

const defaultFreelancerFilters = {
  availability: 'all',
  verified: 'all',
  rate: 'all'
}

const getFiltersFromSearchParams = (searchParams) => ({
  project: {
    category: searchParams.get('projectCategory') || 'all',
    priority: searchParams.get('projectPriority') || 'all',
    budget: searchParams.get('projectBudget') || 'all',
    applied: searchParams.get('projectApplied') || 'all'
  },
  freelancer: {
    availability: searchParams.get('freelancerAvailability') || 'all',
    verified: searchParams.get('freelancerVerified') || 'all',
    rate: searchParams.get('freelancerRate') || 'all'
  }
})

const matchesBudgetRange = (budget, range) => {
  if (range === 'all') return true

  const normalizedBudget = Number(budget)
  if (Number.isNaN(normalizedBudget)) return false

  switch (range) {
    case 'under-500':
      return normalizedBudget < 500
    case '500-2000':
      return normalizedBudget >= 500 && normalizedBudget <= 2000
    case '2000-5000':
      return normalizedBudget > 2000 && normalizedBudget <= 5000
    case '5000-plus':
      return normalizedBudget > 5000
    default:
      return true
  }
}

const matchesRateRange = (rate, range) => {
  if (range === 'all') return true
  if (range === 'unspecified') return rate === null || rate === undefined || Number.isNaN(Number(rate))

  const normalizedRate = Number(rate)
  if (Number.isNaN(normalizedRate)) return false

  switch (range) {
    case 'under-25':
      return normalizedRate < 25
    case '25-50':
      return normalizedRate >= 25 && normalizedRate <= 50
    case '50-100':
      return normalizedRate > 50 && normalizedRate <= 100
    case '100-plus':
      return normalizedRate > 100
    default:
      return true
  }
}

const buildConnectionStatusMap = (connectionsData) => {
  const nextMap = new Map()

  if (!connectionsData) return nextMap

  connectionsData.acceptedConnections?.forEach((connection) => {
    const userId = connection.otherUser?._id
    if (userId) {
      nextMap.set(userId, 'accepted')
    }
  })

  connectionsData.incomingRequests?.forEach((connection) => {
    const userId = connection.otherUser?._id
    if (userId && !nextMap.has(userId)) {
      nextMap.set(userId, 'incoming')
    }
  })

  connectionsData.outgoingRequests?.forEach((connection) => {
    const userId = connection.otherUser?._id
    if (userId && !nextMap.has(userId)) {
      nextMap.set(userId, 'pending')
    }
  })

  return nextMap
}

const ListingTabs = () => {
  const location = useLocation()
  const { currentUser } = useAuth()
  const [searchParams, setSearchParams] = useSearchParams()

  const initialFilters = getFiltersFromSearchParams(searchParams)
  const initialTab = normalizeListingTab(searchParams.get('tab') || location.state?.activeTab)
  const initialPage = Math.max(Number(searchParams.get('page')) || 1, 1)
  const initialSearch = searchParams.get('search') || ''

  const [activeTab, setActiveTab] = useState(initialTab)
  const [isLoading, setIsLoading] = useState(true)
  const [currentPage, setCurrentPage] = useState(initialPage)
  const [projects, setProjects] = useState([])
  const [freelancers, setFreelancers] = useState([])
  const [error, setError] = useState(null)
  const [projectFilters, setProjectFilters] = useState(initialFilters.project)
  const [freelancerFilters, setFreelancerFilters] = useState(initialFilters.freelancer)
  const { searchTerm, updateSearch } = useContext(SearchContext)
  const [searchInput, setSearchInput] = useState(initialSearch)
  const hasInitializedPageReset = useRef(false)
  const [appliedProjectIds, setAppliedProjectIds] = useState(new Set())
  const [favoriteProjectIds, setFavoriteProjectIds] = useState(new Set())
  const [favoritingProjectIds, setFavoritingProjectIds] = useState(new Set())
  const [connectionStatusByFreelancerId, setConnectionStatusByFreelancerId] = useState(new Map())

  useEffect(() => {
    const nextTab = normalizeListingTab(searchParams.get('tab') || location.state?.activeTab)
    const nextPage = Math.max(Number(searchParams.get('page')) || 1, 1)
    const nextSearch = searchParams.get('search') || ''
    const nextFilters = getFiltersFromSearchParams(searchParams)

    if (nextTab !== activeTab) {
      setActiveTab(nextTab)
    }

    if (nextPage !== currentPage) {
      setCurrentPage(nextPage)
    }

    if (nextSearch !== searchTerm) {
      updateSearch(nextSearch)
    }

    if (nextSearch !== searchInput) {
      setSearchInput(nextSearch)
    }

    if (JSON.stringify(nextFilters.project) !== JSON.stringify(projectFilters)) {
      setProjectFilters(nextFilters.project)
    }

    if (JSON.stringify(nextFilters.freelancer) !== JSON.stringify(freelancerFilters)) {
      setFreelancerFilters(nextFilters.freelancer)
    }
  }, [searchParams, location.state])

  useEffect(() => {
    const nextParams = new URLSearchParams(searchParams)

    nextParams.set('tab', activeTab)

    if (currentPage > 1) {
      nextParams.set('page', String(currentPage))
    } else {
      nextParams.delete('page')
    }

    if (searchTerm) {
      nextParams.set('search', searchTerm)
    } else {
      nextParams.delete('search')
    }

    if (projectFilters.category !== 'all') nextParams.set('projectCategory', projectFilters.category)
    else nextParams.delete('projectCategory')

    if (projectFilters.priority !== 'all') nextParams.set('projectPriority', projectFilters.priority)
    else nextParams.delete('projectPriority')

    if (projectFilters.budget !== 'all') nextParams.set('projectBudget', projectFilters.budget)
    else nextParams.delete('projectBudget')

    if (projectFilters.applied !== 'all') nextParams.set('projectApplied', projectFilters.applied)
    else nextParams.delete('projectApplied')

    if (freelancerFilters.availability !== 'all') nextParams.set('freelancerAvailability', freelancerFilters.availability)
    else nextParams.delete('freelancerAvailability')

    if (freelancerFilters.verified !== 'all') nextParams.set('freelancerVerified', freelancerFilters.verified)
    else nextParams.delete('freelancerVerified')

    if (freelancerFilters.rate !== 'all') nextParams.set('freelancerRate', freelancerFilters.rate)
    else nextParams.delete('freelancerRate')

    if (nextParams.toString() !== searchParams.toString()) {
      setSearchParams(nextParams, { replace: true })
    }
  }, [activeTab, currentPage, searchTerm, projectFilters, freelancerFilters, searchParams, setSearchParams])

  const handleSearchSubmit = () => {
    updateSearch(searchInput.trim())
  }

  const handleSearchReset = () => {
    setSearchInput('')
    updateSearch('')
  }

  const handleSearchKeyDown = (event) => {
    if (event.key === 'Enter') {
      handleSearchSubmit()
    }
  }

  useEffect(() => {
    if (!hasInitializedPageReset.current) {
      hasInitializedPageReset.current = true
      return
    }

    setCurrentPage(1)
  }, [activeTab, searchTerm, projectFilters, freelancerFilters])

  // Function to filter projects by search term and project-specific filters
  const filterProjects = (projectsList) => {
    const normalizedSearch = searchTerm.toLowerCase()

    return projectsList.filter((project) => {
      const matchesSearch =
        !searchTerm ||
        project.title.toLowerCase().includes(normalizedSearch) ||
        project.description.toLowerCase().includes(normalizedSearch) ||
        project.skills?.some((skill) => skill.toLowerCase().includes(normalizedSearch))

      const matchesCategory = projectFilters.category === 'all' || project.category === projectFilters.category
      const matchesPriority = projectFilters.priority === 'all' || (project.priority || 'low') === projectFilters.priority
      const matchesBudget = matchesBudgetRange(project.budget, projectFilters.budget)

      const isApplied = appliedProjectIds.has(project._id)
      const matchesApplied = projectFilters.applied === 'all' || (projectFilters.applied === 'not-applied' && !isApplied) || (projectFilters.applied === 'applied' && isApplied)

      return matchesSearch && matchesCategory && matchesPriority && matchesBudget && matchesApplied
    })
  }

  useEffect(() => {
    const loadFavoriteProjects = async () => {
      if (!currentUser) {
        setFavoriteProjectIds(new Set())
        return
      }

      try {
        const favoriteProjects = await getFavoriteProjects()
        setFavoriteProjectIds(new Set(favoriteProjects.map((project) => project._id)))
      } catch (error) {
        console.error('Error loading favorite projects:', error)
        setFavoriteProjectIds(new Set())
      }
    }

    loadFavoriteProjects()
  }, [currentUser?._id])

  useEffect(() => {
    const loadConnections = async () => {
      if (!currentUser) {
        setConnectionStatusByFreelancerId(new Map())
        return
      }

      try {
        const connectionsData = await getMyConnections()
        setConnectionStatusByFreelancerId(buildConnectionStatusMap(connectionsData))
      } catch (error) {
        console.error('Error loading connection states for listings:', error)
        setConnectionStatusByFreelancerId(new Map())
      }
    }

    loadConnections()
  }, [currentUser?._id])

  // Function to filter freelancers by search term and freelancer-specific filters
  const filterFreelancers = (freelancersList) => {
    const normalizedSearch = searchTerm.toLowerCase()

    return freelancersList.filter((freelancer) => {
      const freelancerInfo = freelancer.freelancer || {}

      const matchesSearch = !searchTerm || freelancer.searchText?.includes(normalizedSearch)
      const matchesAvailability = freelancerFilters.availability === 'all' || freelancerInfo.availabilityStatus === freelancerFilters.availability
      const matchesVerified = freelancerFilters.verified === 'all' || (freelancerFilters.verified === 'verified' ? Boolean(freelancerInfo.isEmailVerified) : !freelancerInfo.isEmailVerified)
      const matchesRate = matchesRateRange(freelancerInfo.hourlyRate, freelancerFilters.rate)

      return matchesSearch && matchesAvailability && matchesVerified && matchesRate
    })
  }

  useEffect(() => {
    const loadAppliedProjects = async () => {
      if (!currentUser) {
        setAppliedProjectIds(new Set())
        return
      }

      try {
        const interestedProjects = await getInterestedProjects()
        const appliedIds = new Set(interestedProjects.map((project) => project._id))
        setAppliedProjectIds(appliedIds)
      } catch (error) {
        console.error('Error loading applied projects:', error)
        setAppliedProjectIds(new Set())
      }
    }

    loadAppliedProjects()
  }, [currentUser?._id])

  // Fetch projects from API
  useEffect(() => {
    const fetchProjects = async () => {
      if (activeTab === 'projects') {
        try {
          setIsLoading(true)
          setError(null)
          const data = await getAllProjects()
          setProjects(data)
        } catch (err) {
          console.error('Error fetching projects:', err)
          setError('Failed to load projects. Please try again.')
        } finally {
          setIsLoading(false)
        }
      } else {
        // Fetch announcements from freelancers
        try {
          setIsLoading(true)
          setError(null)

          // Fetch all active announcements with populated user data
          const announcements = await getAllAnnouncements()

          // Filter to only include announcements from freelancers or both users
          const filteredAnnouncements = announcements.filter((announcement) => announcement.userId && ['freelancer', 'both'].includes(announcement.userId.userType))

          const mapped = filteredAnnouncements.map(buildFreelancerListingModel)

          setFreelancers(mapped)
        } catch (err) {
          console.error('Error fetching freelancers:', err)
          setError('Failed to load freelancers. Please try again.')
        } finally {
          setIsLoading(false)
        }
      }
    }

    fetchProjects()
  }, [activeTab])

  const handleToggleFavoriteProject = async (projectId) => {
    if (!currentUser) {
      alert('Please login to favorite projects')
      return
    }

    setFavoritingProjectIds((current) => {
      const next = new Set(current)
      next.add(projectId)
      return next
    })

    try {
      const isAlreadyFavorited = favoriteProjectIds.has(projectId)

      if (isAlreadyFavorited) {
        await removeFromFavorites(projectId)
      } else {
        await addToFavorites(projectId)
      }

      setFavoriteProjectIds((current) => {
        const next = new Set(current)

        if (next.has(projectId)) {
          next.delete(projectId)
        } else {
          next.add(projectId)
        }

        return next
      })
    } catch (error) {
      console.error('Error toggling favorite project:', error)
    } finally {
      setFavoritingProjectIds((current) => {
        const next = new Set(current)
        next.delete(projectId)
        return next
      })
    }
  }

  // Pagination
  const itemsPerPage = 6
  const indexOfLastItem = currentPage * itemsPerPage
  const indexOfFirstItem = indexOfLastItem - itemsPerPage
  const filteredProjects = filterProjects(projects)
  const filteredFreelancers = filterFreelancers(freelancers)
  const projectCategories = [...new Set(projects.map((project) => project.category).filter(Boolean))].sort((a, b) => a.localeCompare(b))

  const currentItems = activeTab === 'projects' ? filteredProjects.slice(indexOfFirstItem, indexOfLastItem) : filteredFreelancers.slice(indexOfFirstItem, indexOfLastItem)

  const totalPages = Math.ceil((activeTab === 'projects' ? filteredProjects.length : filteredFreelancers.length) / itemsPerPage)
  const activeProjectFilterCount = Object.values(projectFilters).filter((value) => value !== 'all').length
  const activeFreelancerFilterCount = Object.values(freelancerFilters).filter((value) => value !== 'all').length
  const activeFilterCount = activeTab === 'projects' ? activeProjectFilterCount : activeFreelancerFilterCount
  const visibleResultsCount = activeTab === 'projects' ? filteredProjects.length : filteredFreelancers.length

  return (
    <section className='w-full pt-[96px] md:pt-[104px] pb-20 relative z-[1]'>
      {/* Main container */}
      <div className='container mx-auto px-4 relative z-10'>
        <div className='max-w-8xl mx-auto'>
          {/* Projects and Freelancers tabs */}
          <div className='flex w-full'>
            <button
              onClick={() => setActiveTab('projects')}
              className={`flex-1 py-4 px-6 flex items-center justify-center gap-2 border-b-2 transition-all duration-300 hover:shadow-lg ${
                activeTab === 'projects'
                  ? 'border-accent text-accent dark:bg-light/5 bg-primary/5'
                  : 'dark:border-light/10 border-primary/10 dark:text-light/60 text-primary/60 dark:hover:text-light/80 hover:text-primary/80 dark:hover:bg-light/5 hover:bg-primary/5'
              }`}>
              <FaBriefcase className='text-lg' />
              <span className='font-medium'>Projects</span>
            </button>
            <button
              onClick={() => setActiveTab('freelancers')}
              className={`flex-1 py-4 px-6 flex items-center justify-center gap-2 border-b-2 transition-all duration-300 hover:shadow-lg ${
                activeTab === 'freelancers'
                  ? 'border-accent text-accent dark:bg-light/5 bg-primary/5'
                  : 'dark:border-light/10 border-primary/10 dark:text-light/60 text-primary/60 dark:hover:text-light/80 hover:text-primary/80 dark:hover:bg-light/5 hover:bg-primary/5'
              }`}>
              <FaUser className='text-lg' />
              <span className='font-medium'>Freelancers</span>
            </button>
          </div>

          {/* Content section with animation */}
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, x: activeTab === 'projects' ? -20 : 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: activeTab === 'projects' ? 20 : -20 }}
            transition={{ duration: 0.4, ease: 'easeOut' }}
            className='rounded-b-lg p-12'>
            <div className='mb-8 overflow-hidden rounded-lg border dark:border-light/10 border-primary/10'>
              <div className='flex flex-col gap-5 border-b dark:border-light/10 border-primary/10 px-5 py-5 md:px-6'>
                <div className='flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between'>
                  <div className='flex flex-wrap items-center gap-2'>
                    <span className='inline-flex items-center rounded-full bg-accent/10 px-3 py-1 text-xs font-semibold uppercase tracking-[0.18em] text-accent'>
                      {activeTab === 'projects' ? 'Project discovery' : 'Freelancer discovery'}
                    </span>
                    <span className='inline-flex items-center rounded-full dark:bg-light/10 bg-primary/5 px-3 py-1 text-xs font-medium theme-text-secondary'>
                      {visibleResultsCount} result{visibleResultsCount === 1 ? '' : 's'}
                    </span>
                    {activeFilterCount > 0 && (
                      <span className='inline-flex items-center rounded-full bg-emerald-500/10 px-3 py-1 text-xs font-medium text-emerald-600 dark:text-emerald-300'>
                        {activeFilterCount} active filter{activeFilterCount === 1 ? '' : 's'}
                      </span>
                    )}
                  </div>

                  <button
                    onClick={() => {
                      if (activeTab === 'projects') {
                        setProjectFilters(defaultProjectFilters)
                      } else {
                        setFreelancerFilters(defaultFreelancerFilters)
                      }
                    }}
                    className='inline-flex items-center justify-center rounded-full border dark:border-light/10 border-primary/10 px-4 py-2 text-sm font-medium theme-text-secondary hover:border-accent hover:text-accent hover:bg-accent/5 transition-all duration-300 hover:shadow-lg'>
                    Clear filters
                  </button>
                </div>

                <div className='grid grid-cols-1 gap-3 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-end'>
                  <label className='block'>
                    <span className='mb-2 block text-xs font-semibold uppercase tracking-[0.16em] theme-text-secondary'>{activeTab === 'projects' ? 'Search projects' : 'Search freelancers'}</span>
                    <div className='relative'>
                      <FaSearch className='pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-accent/80' size={16} />
                      <input
                        type='text'
                        value={searchInput}
                        onChange={(event) => setSearchInput(event.target.value)}
                        onKeyDown={handleSearchKeyDown}
                        placeholder={activeTab === 'projects' ? 'Search by title, description, or skills' : 'Search by name, specialty, or skills'}
                        className='h-[50px] w-full rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 pl-11 pr-4 theme-text outline-none transition-all duration-300 focus:bg-light/20 dark:focus:bg-light/20 focus:border-accent focus:ring-2 focus:ring-accent/20 hover:scale-[1.02] hover:shadow-lg'
                      />
                    </div>
                  </label>

                  <div className='flex flex-col gap-3 sm:flex-row'>
                    <button
                      onClick={handleSearchSubmit}
                      className='inline-flex h-[50px] items-center justify-center rounded-lg bg-accent px-5 text-sm font-semibold text-white transition-all duration-300 hover:bg-accent/90 hover:shadow-lg'>
                      Search
                    </button>

                    <button
                      onClick={handleSearchReset}
                      className='inline-flex h-[50px] items-center justify-center rounded-lg border dark:border-light/10 border-primary/10 px-5 text-sm font-medium theme-text-secondary transition-all duration-300 hover:border-accent hover:text-accent hover:bg-accent/5 hover:shadow-lg'>
                      Reset search
                    </button>
                  </div>
                </div>
              </div>

              {activeTab === 'projects' ? (
                <div className='grid grid-cols-1 gap-4 p-5 md:grid-cols-2 xl:grid-cols-4 md:p-6'>
                  <label className='group rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 px-4 py-4 transition-all hover:border-accent/40 hover:bg-light/20 dark:hover:bg-light/20'>
                    <span className='mt-1 block text-sm theme-text-secondary'>Match projects by discipline</span>
                    <select
                      value={projectFilters.category}
                      onChange={(event) => setProjectFilters((current) => ({ ...current, category: event.target.value }))}
                      className='theme-select mt-4 w-full rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 px-4 py-3 theme-text outline-none transition-all focus:border-accent focus:ring-2 focus:ring-accent/20 hover:scale-[1.02]'>
                      <option value='all'>All categories</option>
                      {projectCategories.map((category) => (
                        <option key={category} value={category}>
                          {category}
                        </option>
                      ))}
                    </select>
                  </label>

                  <label className='group rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 px-4 py-4 transition-all duration-300 hover:border-accent/40 hover:bg-light/20 dark:hover:bg-light/20 hover:shadow-lg'>
                    <span className='mt-1 block text-sm theme-text-secondary'>Surface the urgency level you want</span>
                    <select
                      value={projectFilters.priority}
                      onChange={(event) => setProjectFilters((current) => ({ ...current, priority: event.target.value }))}
                      className='theme-select mt-4 w-full rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 px-4 py-3 theme-text outline-none transition-all duration-300 focus:border-accent focus:ring-2 focus:ring-accent/20 hover:scale-[1.02] hover:shadow-lg'>
                      <option value='all'>Any priority</option>
                      <option value='low'>Low</option>
                      <option value='medium'>Medium</option>
                      <option value='high'>High</option>
                    </select>
                  </label>

                  <label className='group rounded-lg border dark:border-light/10 border-primary/10 bg-light/10 dark:bg-light/10 px-4 py-4 transition-all duration-300 hover:border-accent/40 hover:bg-light/20 dark:hover:bg-light/20 hover:shadow-lg'>
