              </div>
            </div>

            <div className='space-y-3 border-t border-primary/10 pt-3 dark:border-light/10'>
              <div className='flex flex-wrap items-center gap-2'>
                <span className='text-[11px] font-semibold uppercase tracking-[0.16em] theme-text-secondary'>Saved views</span>
                {acceptedPresetOptions.map((preset) => (
                  <button
                    key={preset.key}
                    type='button'
                    onClick={() => applyAcceptedPreset(preset.key, setAcceptedFilter, setAcceptedSearch)}
                    className={`inline-flex items-center rounded-full px-3 py-1.5 text-[11px] font-medium transition-all ${
                      activeAcceptedPresetKey === preset.key ? 'bg-accent text-white' : 'bg-primary/5 theme-text-secondary hover:bg-accent/10 hover:text-accent dark:bg-light/5'
                    }`}>
                    {preset.label}
                  </button>
                ))}
              </div>

              <div className='flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between'>
                <p className='text-[11px] font-medium uppercase leading-5 tracking-[0.14em] theme-text-secondary sm:text-xs'>
                  Showing {filteredAcceptedCount} of {connections.acceptedConnections.length} connections
                  {pinnedAcceptedCount > 0 ? ` ΓÇó Pinned: ${pinnedAcceptedCount}` : ''}
                  {activeAcceptedPresetKey !== 'custom' ? ` ΓÇó View: ${activeAcceptedPresetLabel}` : ''}
                  {acceptedFilter !== 'all' ? ` ΓÇó Filter: ${acceptedFilterOptions.find((option) => option.key === acceptedFilter)?.label}` : ''}
                  {acceptedSearch.trim() ? ` ΓÇó Search: ${acceptedSearch.trim()}` : ''}
                </p>

                <button
                  type='button'
                  onClick={() => {
                    setAcceptedFilter('all')
                    setAcceptedSearch('')
                  }}
                  className='inline-flex w-full items-center justify-center rounded-full border border-primary/10 px-4 py-2 text-sm font-medium theme-text-secondary transition-all hover:border-accent hover:bg-accent/5 hover:text-accent dark:border-light/10 sm:w-auto'>
                  Clear tools
                </button>
              </div>
            </div>
          </div>
        </div>

        <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent flex min-h-[112px] flex-col justify-between rounded-2xl px-5 py-4 border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
          <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Connections</p>
          <p className='mt-2 text-3xl font-bold theme-text'>{connections.summary.connectionsCount}</p>
        </div>

        <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent flex min-h-[112px] flex-col justify-between rounded-2xl px-5 py-4 border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
          <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Incoming</p>
          <p className='mt-2 text-3xl font-bold theme-text'>{connections.summary.incomingCount}</p>
        </div>

        <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent flex min-h-[112px] flex-col justify-between rounded-2xl px-5 py-4 border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
          <p className='text-xs font-semibold uppercase tracking-[0.14em] theme-text-secondary'>Pending</p>
          <p className='mt-2 text-3xl font-bold theme-text'>{connections.summary.outgoingCount}</p>
        </div>
      </div>

      {sections.map((section) => (
        <div key={section.key} className='space-y-4'>
          <div className='space-y-1'>
            <div className='flex flex-wrap items-center gap-2'>
              <h2 className='text-xl font-semibold theme-text'>{section.title}</h2>
              <span className='inline-flex items-center rounded-full bg-primary/5 px-2.5 py-1 text-[11px] font-medium theme-text-secondary dark:bg-light/10'>{section.items.length}</span>
            </div>
            <p className='text-sm theme-text-secondary'>{section.description}</p>
          </div>

          {section.items.length === 0 ? (
            <div className='rounded-2xl border border-dashed border-primary/10 bg-primary/[0.02] px-6 py-10 text-center theme-text-secondary dark:border-light/10 dark:bg-light/[0.02]'>
              <p>{section.emptyMessage}</p>
              {section.key === 'accepted' && (acceptedFilter !== 'all' || acceptedSearch.trim()) && (
                <button
                  type='button'
                  onClick={() => {
                    setAcceptedFilter('all')
                    setAcceptedSearch('')
                  }}
                  className='mt-4 inline-flex rounded-full bg-accent/10 px-4 py-2 text-sm font-medium text-accent transition-colors hover:bg-accent hover:text-white'>
                  Reset Network Tools
                </button>
              )}
            </div>
          ) : (
            <div className='grid gap-3 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4'>
              {section.items.map((connection) => {
                const otherUser = connection.otherUser || {}
                const canOpenFreelancerProfile = ['freelancer', 'both'].includes(otherUser.userType)
                const locationLabel = otherUser.showLocationPublic && otherUser.location ? otherUser.location : ''
                const canDirectMessage = otherUser.allowDirectMessages !== false
                const canInviteToProjects = otherUser.allowProjectInvites !== false
                const activityLabel = formatConnectionActivity(connection, section.key)
                const isPinned = pinnedConnectionIds.includes(connection._id)
                const isAcceptedCard = section.key === 'accepted'
                const sectionBadge = getConnectionSectionBadge(section.key)
                const connectionNote = connectionNotes[connection._id] || ''
                const isEditingNote = editingConnectionNoteId === connection._id

                return (
                  <motion.div
                    key={connection._id}
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    className={`h-full rounded-2xl border border-accent/15 bg-gradient-to-br from-white via-white to-accent/5 p-4 shadow-[0_14px_30px_rgba(0,0,0,0.06)] transition-all hover:-translate-y-0.5 hover:shadow-[0_18px_38px_rgba(0,0,0,0.1)] sm:p-[18px] dark:border-accent/20 dark:from-light/[0.06] dark:via-light/[0.04] dark:to-accent/10`}>
                    <div className='flex h-full flex-col gap-3.5'>
                      <div className='flex items-start gap-2.5'>
                        <img src={otherUser.profilePicture || `https://i.pravatar.cc/150?u=${otherUser._id}`} alt={otherUser.firstName || 'User'} className='h-10 w-10 rounded-full object-cover border border-accent/20' />
                        <div className='min-w-0'>
                          <div className='mb-2 flex flex-wrap items-center gap-2'>
                            <span className={`inline-flex rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[0.16em] ring-1 ring-inset ring-current/10 ${sectionBadge.className}`}>
                              {sectionBadge.label}
                            </span>
                            {isAcceptedCard && isPinned && (
                              <span className='inline-flex items-center gap-1 rounded-full bg-accent/10 px-2 py-0.5 text-[10px] font-medium text-accent'>
                                <FaThumbtack size={10} />
                                <span>Pinned</span>
                              </span>
                            )}
                          </div>

                          <div className='flex flex-wrap items-center gap-2'>
                            <h3 className='text-sm font-semibold theme-text'>{[otherUser.firstName, otherUser.lastName].filter(Boolean).join(' ') || 'User'}</h3>
                            <VerificationBadge isVerified={otherUser.isEmailVerified} />
                          </div>
                          <p className='mt-1 text-[11px] leading-5 theme-text-secondary'>{otherUser.headline || 'Professional profile'}</p>

                          {activityLabel && (
                            <div className='mt-2 inline-flex items-center gap-1.5 rounded-full border border-accent/15 bg-accent/10 px-2.5 py-1 text-[11px] font-medium text-accent'>
                              <FaClock size={10} />
                              <span>{activityLabel}</span>
                            </div>
                          )}

                          <div className='mt-2 flex flex-wrap gap-1.5 text-[11px] theme-text-secondary'>
                            {otherUser.availabilityStatus ? <span className='rounded-full bg-primary/5 px-2 py-0.5 dark:bg-light/5'>{otherUser.availabilityStatus.replace('_', ' ')}</span> : null}
                            {locationLabel ? <span className='rounded-full border border-primary/10 bg-primary/5 px-2 py-0.5 dark:border-light/10 dark:bg-light/5'>{locationLabel}</span> : null}
                          </div>

                          {isAcceptedCard && (connectionNote || isEditingNote) && (
                            <div className='mt-2 rounded-xl border border-primary/10 bg-white/70 px-3 py-2 dark:border-light/10 dark:bg-light/[0.05]'>
                              <div className='flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-[0.14em] theme-text-secondary'>
                                <FaRegStickyNote size={10} />
                                <span>Private Note</span>
                              </div>

                              {isEditingNote ? (
                                <div className='mt-2 space-y-2'>
                                  <textarea
                                    value={connectionNoteDraft}
                                    onChange={(event) => setConnectionNoteDraft(event.target.value)}
                                    rows={3}
                                    placeholder='Add a quick reminder about this connection'
                                    className='w-full resize-none rounded-lg border border-primary/10 bg-white/90 px-3 py-2 text-[12px] leading-5 theme-text outline-none transition-colors focus:border-accent dark:border-light/10 dark:bg-light/[0.08]'
                                  />
                                  <div className='flex flex-wrap gap-2'>
                                    <button type='button' onClick={() => handleSubmitConnectionNote(connection._id)} className={compactActionClasses.accent}>
                                      Save Note
                                    </button>
                                    <button type='button' onClick={handleCancelEditingConnectionNote} className={compactActionClasses.neutral}>
                                      Cancel
                                    </button>
                                  </div>
                                </div>
                              ) : (
                                <p className='mt-1 text-[11px] leading-5 theme-text-secondary'>{connectionNote}</p>
                              )}
                            </div>
                          )}
                        </div>
                      </div>

                      <div className='mt-auto flex flex-wrap items-center gap-1.5 border-t border-primary/10 pt-3 dark:border-light/10'>
                        {section.key === 'incoming' && (
                          <>
                            <button type='button' onClick={() => handleAction(connection._id, 'accept')} disabled={actionId === connection._id} className={`${compactActionClasses.success} disabled:opacity-60`}>
                              <FaCheck />
                              <span>Accept</span>
                            </button>
                            <button type='button' onClick={() => handleAction(connection._id, 'decline')} disabled={actionId === connection._id} className={`${compactActionClasses.danger} disabled:opacity-60`}>
                              <FaTimes />
                              <span>Decline</span>
                            </button>
                          </>
                        )}

                        {section.key === 'outgoing' && (
                          <button type='button' onClick={() => handleAction(connection._id, 'remove')} disabled={actionId === connection._id} className={compactActionClasses.accent}>
                            <FaClock />
                            <span>Cancel Request</span>
                          </button>
                        )}

                        {section.key === 'accepted' && canDirectMessage && (
                          <button
                            type='button'
                            onClick={() => handleOpenDirectMessage(otherUser)}
                            className='inline-flex items-center gap-1.5 rounded-lg bg-accent px-2.5 py-1.5 text-[11px] font-medium text-white transition-colors hover:bg-accent/90'>
                            <FaEnvelope />
                            <span>Message</span>
                          </button>
                        )}

                        {section.key === 'accepted' && canInviteToProjects && (
                          <button type='button' onClick={() => handleOpenProjectInvite(otherUser)} className={compactActionClasses.accentSoft}>
                            <FaBriefcase />
                            <span>Invite to Project</span>
                          </button>
                        )}

                        {section.key === 'accepted' && (
                          <button type='button' onClick={() => handleTogglePinnedConnection(connection._id)} className={isPinned ? compactActionClasses.accent : compactActionClasses.subtle}>
                            <FaThumbtack />
                            <span>{isPinned ? 'Unpin' : 'Pin'}</span>
                          </button>
                        )}

                        {section.key === 'accepted' && isPinned && (
                          <button
                            type='button'
                            onClick={() => (isEditingNote ? handleCancelEditingConnectionNote() : handleStartEditingConnectionNote(connection._id, connectionNote))}
                            className={isEditingNote ? compactActionClasses.neutral : compactActionClasses.subtle}>
                            <FaRegStickyNote />
                            <span>{isEditingNote ? 'Close Note' : connectionNote ? 'Edit Note' : 'Add Note'}</span>
                          </button>
                        )}

                        {section.key === 'accepted' && canOpenFreelancerProfile ? (
                          <button type='button' onClick={() => navigate(`/freelancer/${otherUser._id}`, { state: { returnTo: '/profile' } })} className={compactActionClasses.neutral}>
                            <FaArrowRight />
                            <span>View Profile</span>
                          </button>
                        ) : null}

                        {section.key === 'accepted' && (
                          <button type='button' onClick={() => handleAction(connection._id, 'remove')} disabled={actionId === connection._id} className={`${compactActionClasses.danger} disabled:opacity-60`}>
                            <FaUserFriends />
                            <span>Remove</span>
                          </button>
                        )}
                      </div>
                    </div>
                  </motion.div>
                )
              })}
            </div>
          )}
        </div>
      ))}
      <DirectContactModal isOpen={showContactModal} onClose={() => setShowContactModal(false)} freelancer={selectedConnectionUser} />
      <HireFreelancerModal isOpen={showHireModal} onClose={() => setShowHireModal(false)} freelancer={selectedConnectionUser} />
    </div>
  )
}

export default ConnectionsTab

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import PropTypes from 'prop-types'
import { FaBriefcase, FaPlus, FaEdit, FaTrash, FaPlay, FaPause, FaCalendar } from 'react-icons/fa'
import CreateAnnouncementModal from '../../modal/CreateAnnouncementModal'
import { getUserAnnouncements, deleteAnnouncement, toggleAnnouncementStatus } from '../../services/announcementService'
import LoadingSpinner from '../shared/LoadingSpinner'
import AvailabilityCalendar from '../shared/AvailabilityCalendar'
import SkillsList from '../shared/SkillsList'

const FreelanceTab = ({ user }) => {
  const isVerified = Boolean(user?.isEmailVerified)
  // Modal state
  const [isModalOpen, setIsModalOpen] = useState(false)

  const [announcements, setAnnouncements] = useState([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [editingAnnouncement, setEditingAnnouncement] = useState(null)

  const fetchAnnouncements = async () => {
    try {
      setLoading(true)
      setError('')
      const data = await getUserAnnouncements()
      setAnnouncements(data)
    } catch (err) {
      console.error('Error fetching announcements:', err)
      setError('Failed to load announcements')
    } finally {
      setLoading(false)
    }
  }

  // Fetch announcements when component mounts
  useEffect(() => {
    fetchAnnouncements()
  }, [])

  const handleDeleteAnnouncement = async (announcementId) => {
    if (window.confirm('Are you sure you want to delete this announcement?')) {
      try {
        await deleteAnnouncement(announcementId)
        setAnnouncements(announcements.filter((a) => a._id !== announcementId))
      } catch (err) {
        console.error('Error deleting announcement:', err)
        setError('Failed to delete announcement')
      }
    }
  }

  const handleEditAnnouncement = (announcement) => {
    setEditingAnnouncement(announcement)
    setIsModalOpen(true)
  }

  const handleToggleStatus = async (announcementId) => {
    try {
      const response = await toggleAnnouncementStatus(announcementId)
      const updatedAnnouncement = response.announcement
      setAnnouncements(announcements.map((a) => (a._id === announcementId ? updatedAnnouncement : a)))
    } catch (err) {
      console.error('Error toggling announcement status:', err)
      setError('Failed to toggle announcement status')
    }
  }

  return (
    <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} transition={{ duration: 0.3 }} className='space-y-6'>
      {/* Header with Create Announcement Button */}
      <div className='flex items-center justify-between'>
        <div className='flex items-center gap-3'>
          <FaBriefcase className='text-accent text-xl' />
          <h2 className='text-2xl font-bold theme-text'>My Freelance Announcements</h2>
        </div>
        <motion.button
          onClick={() => {
            if (!isVerified) return
            setIsModalOpen(true)
          }}
          disabled={!isVerified}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className='flex items-center gap-2 bg-accent text-white px-4 py-2 rounded-lg hover:bg-accent/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed'>
          <FaPlus />
          <span>Create Announcement</span>
        </motion.button>
      </div>

      {!isVerified && (
        <div className='rounded-lg border border-amber-300/40 bg-amber-500/10 px-4 py-3 text-sm text-amber-700 dark:text-amber-300'>
          Verify your email to publish freelance announcements. You can still edit your profile, but announcement publishing stays locked until verification is complete.
        </div>
      )}

      {/* Announcements List or Empty State */}
      <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent p-8 rounded-lg text-center border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
        {loading ? (
          <div className='flex justify-center py-8'>
            <LoadingSpinner />
          </div>
        ) : error ? (
          <div className='bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 p-4 rounded-lg'>{error}</div>
        ) : announcements.length === 0 ? (
          <div className='space-y-4 text-center'>
            <FaBriefcase className='text-5xl text-primary/40 dark:text-light/40 mx-auto' />
            <p className='theme-text-secondary text-lg'>No announcements yet. Create your first freelance announcement to get started!</p>
            <motion.button
              onClick={() => {
                if (!isVerified) return
                setIsModalOpen(true)
              }}
              disabled={!isVerified}
              whileHover={isVerified ? { scale: 1.05 } : {}}
              whileTap={isVerified ? { scale: 0.95 } : {}}
              className='inline-flex items-center gap-2 bg-accent text-white px-6 py-3 rounded-lg hover:bg-accent/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed'>
              <FaPlus />
              <span>{isVerified ? 'Create Your First Announcement' : 'Verify Email to Create Announcement'}</span>
            </motion.button>
          </div>
        ) : (
          <div className='grid grid-cols-1 md:grid-cols-3 gap-4'>
            {announcements.map((announcement, index) => (
              <motion.div
                key={announcement._id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                whileHover={{
                  scale: 1.02,
                  transition: { duration: 0.1 }
                }}
                transition={{ duration: 0.2, delay: index * 0.1 }}
                className='p-6 rounded-lg bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent hover:shadow-lg hover:-translate-y-1 transition-all duration-300 group backdrop-blur-sm border border-primary/10 dark:border-light/10'>
                {/* Title Section */}
                <div className='flex items-start gap-4 mb-4'>
                  <div className='flex-1'>
                    <h3 className='flex text-xl font-bold mb-2 theme-text'>{announcement.title}</h3>
                    <div className='flex gap-2 flex-wrap'>{announcement.skills && announcement.skills.length > 0 && <SkillsList skills={announcement.skills} maxDisplay={2} />}</div>
                  </div>
                </div>

                {/* Rate Section */}
                <div className='flex items-center justify-between mb-3'>
                  <div className='flex items-center gap-1'>
                    <span className='font-medium theme-text'>Hourly Rate</span>
                  </div>
                  <span className='font-bold text-accent text-lg'>Γé¼{announcement.hourlyRate}/hr</span>
                </div>

                {/* Background Section */}
                <div className='flex items-center gap-2 theme-text-secondary text-sm line-clamp-2'>
                  <span>{announcement.background}</span>
                </div>

                {/* Status Badge */}
                <div className='mt-4 flex items-center justify-between'>
                  <span
                    className={`inline-block px-3 py-1 rounded-full text-xs font-bold ${
                      announcement.isActive ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300' : 'bg-primary/10 dark:bg-light/10 text-primary/70 dark:text-light/70'
                    }`}>
                    {announcement.isActive ? 'ΓùÅ Active' : 'Γùï Paused'}
                  </span>
                  <div className='flex gap-2'>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleToggleStatus(announcement._id)}
                      className={`p-1.5 rounded transition-colors ${
                        announcement.isActive ? 'text-orange-600 dark:text-orange-300 hover:bg-orange-100 dark:hover:bg-orange-900/30' : 'text-green-600 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30'
                      }`}
                      title={announcement.isActive ? 'Pause announcement' : 'Resume announcement'}>
                      {announcement.isActive ? <FaPause size={14} /> : <FaPlay size={14} />}
                    </motion.button>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleEditAnnouncement(announcement)}
                      className='p-1.5 rounded text-blue-600 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-blue-900/30 transition-colors'>
                      <FaEdit size={14} />
                    </motion.button>
                    <motion.button
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleDeleteAnnouncement(announcement._id)}
                      className='p-1.5 rounded text-red-600 dark:text-red-300 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors'>
                      <FaTrash size={14} />
                    </motion.button>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>
      {/* Create Announcement Modal */}
      <CreateAnnouncementModal
        isOpen={isModalOpen}
        onClose={() => {
          setIsModalOpen(false)
          setEditingAnnouncement(null)
        }}
        editingAnnouncement={editingAnnouncement}
        isVerified={isVerified}
        onAnnouncementCreated={(updatedAnnouncement) => {
          if (editingAnnouncement) {
            // Update existing announcement
            setAnnouncements(announcements.map((a) => (a._id === updatedAnnouncement._id ? updatedAnnouncement : a)))
            setEditingAnnouncement(null)
          } else {
            // Add new announcement
            setAnnouncements([updatedAnnouncement, ...announcements])
          }
        }}
      />

      {/* Availability Calendar Section */}
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }} className='space-y-4'>
        <div className='flex items-center gap-3'>
          <FaCalendar className='text-accent text-xl' />
          <h2 className='text-2xl font-bold theme-text'>My Availability</h2>
        </div>
        <div className='bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent rounded-lg overflow-hidden border border-primary/10 dark:border-light/10'>
          <AvailabilityCalendar freelancerId={user?._id} isOwnProfile={true} isPublicView={false} />
        </div>
      </motion.div>
    </motion.div>
  )
}

FreelanceTab.propTypes = {
  user: PropTypes.shape({
    _id: PropTypes.string,
    isEmailVerified: PropTypes.bool
  })
}

export default FreelanceTab

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  FaUser,
  FaEnvelope,
  FaPhone,
  FaMapMarkerAlt,
  FaTools,
  FaBook,
  FaGlobe,
  FaGithub,
  FaLinkedin,
  FaTwitter,
  FaStar,
  FaLanguage,
  FaCertificate,
  FaList,
  FaBriefcase,
  FaSyncAlt,
  FaChevronDown,
  FaClock,
  FaEye
} from 'react-icons/fa'
import { toast } from 'react-toastify'
import { useAuth } from '../../context/AuthContext'
import LoadingSpinner from '../shared/LoadingSpinner'
import { calculateProfileCompleteness } from '../../utils/profileCompleteness'

// Initial form state with empty values
const initialFormState = {
  fullName: '',
  email: '',
  phone: '',
  location: '',
  skills: '',
  bio: '',
  headline: '',
  availabilityStatus: 'available',
  profileVisibility: 'public',
  responseTime: 'within_24_hours',
  servicesOffered: '',
  tools: '',
  workPreference: 'flexible',
  yearsOfExperience: '',
  minimumProjectBudget: '',
  preferredProjectSize: 'flexible',
  preferredEngagements: '',
  timezone: '',
  availabilityDetails: '',
  industries: '',
  showLocationPublic: true,
  showHourlyRate: true,
  allowDirectMessages: true,
  allowProjectInvites: true,
  emailNotificationsEnabled: true,
  emailNotificationsMessages: true,
  emailNotificationsConnections: true,
  emailNotificationsProjects: true,
  website: '',
  github: '',
  linkedin: '',
  twitter: '',
  hourlyRate: '',
  experienceLevel: 'entry',
  languages: '',
  certifications: '',
  serviceCategories: '',
  upworkProfile: '',
  fiverrProfile: '',
  profilePicture: ''
}

const ProfileSettings = () => {
  const { currentUser, updateUserProfile } = useAuth()
  const profileCompleteness = calculateProfileCompleteness(currentUser)
  const missingRequired = profileCompleteness?.missingRequired ?? []
  const missingOptional = profileCompleteness?.missingOptional ?? []
  const userRole = currentUser?.userType || 'freelancer'
  // Show freelancer fields for freelancer, both roles, and admin
  const showFreelancerSection = userRole === 'freelancer' || userRole === 'both' || userRole === 'admin'

  const [formData, setFormData] = useState(initialFormState)
  const [savedFormData, setSavedFormData] = useState(initialFormState)
  const [errors, setErrors] = useState({})
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isLoading, setIsLoading] = useState(!currentUser)

  // Helper function to populate form with user data
  const populateFormWithUserData = (user) => {
    if (!user) return

    const nextFormData = {
      fullName: `${user.firstName || ''} ${user.lastName || ''}`.trim(),
      email: user.email || '',
      phone: user.phone || '',
      location: user.location || '',
      skills: user.skills || '',
      bio: user.bio || '',
      headline: user.headline || '',
      availabilityStatus: user.availabilityStatus || 'available',
      profileVisibility: user.profileVisibility || 'public',
      responseTime: user.responseTime || 'within_24_hours',
      servicesOffered: user.servicesOffered || '',
      tools: user.tools || '',
      workPreference: user.workPreference || 'flexible',
      yearsOfExperience: user.yearsOfExperience ?? '',
      minimumProjectBudget: user.minimumProjectBudget ?? '',
      preferredProjectSize: user.preferredProjectSize || 'flexible',
      preferredEngagements: Array.isArray(user.preferredEngagements) ? user.preferredEngagements.join(', ') : '',
      timezone: user.timezone || '',
      availabilityDetails: user.availabilityDetails || '',
      industries: user.industries || '',
      showLocationPublic: user.showLocationPublic ?? true,
      showHourlyRate: user.showHourlyRate ?? true,
      allowDirectMessages: user.allowDirectMessages ?? true,
      allowProjectInvites: user.allowProjectInvites ?? true,
      emailNotificationsEnabled: user.emailNotificationsEnabled ?? true,
      emailNotificationsMessages: user.emailNotificationsMessages ?? true,
      emailNotificationsConnections: user.emailNotificationsConnections ?? true,
      emailNotificationsProjects: user.emailNotificationsProjects ?? true,
      website: user.website || '',
      github: user.github || '',
      linkedin: user.linkedin || '',
      twitter: user.twitter || '',
      profilePicture: user.profilePicture || '',
      hourlyRate: user.hourlyRate ?? '',
      experienceLevel: user.experienceLevel || 'entry',
      languages: user.languages || '',
      certifications: user.certifications || '',
      serviceCategories: user.serviceCategories || '',
      upworkProfile: user.upworkProfile || '',
      fiverrProfile: user.fiverrProfile || ''
    }

    setFormData(nextFormData)
    setSavedFormData(nextFormData)
    setIsLoading(false)
  }

  // Update form data when currentUser becomes available
  useEffect(() => {
    if (!currentUser) {
      setIsLoading(true)
      return
    }

    populateFormWithUserData(currentUser)
  }, [currentUser])

  // Handle form field changes
  const handleChange = (e) => {
    const { name, value, type, checked } = e.target
    const nextValue = type === 'checkbox' ? checked : value

    setFormData((prev) => {
      if (name === 'emailNotificationsEnabled') {
        if (!checked) {
          return {
            ...prev,
            emailNotificationsEnabled: false,
            emailNotificationsMessages: false,
            emailNotificationsConnections: false,
            emailNotificationsProjects: false
          }
        }

        const hasAnyEmailCategoryEnabled = prev.emailNotificationsMessages || prev.emailNotificationsConnections || prev.emailNotificationsProjects

        return {
          ...prev,
          emailNotificationsEnabled: true,
          emailNotificationsMessages: hasAnyEmailCategoryEnabled ? prev.emailNotificationsMessages : true,
          emailNotificationsConnections: hasAnyEmailCategoryEnabled ? prev.emailNotificationsConnections : true,
          emailNotificationsProjects: hasAnyEmailCategoryEnabled ? prev.emailNotificationsProjects : true
        }
      }

      return {
        ...prev,
        [name]: nextValue
      }
    })

    setErrors((prev) => {
      if (!prev[name]) return prev

      const nextErrors = { ...prev }
      delete nextErrors[name]
      return nextErrors
    })
  }

  const hasUnsavedChanges = JSON.stringify(formData) !== JSON.stringify(savedFormData)
  const currentAvatarUrl = formData.profilePicture || `https://i.pravatar.cc/150?u=${currentUser?._id || 'default'}`
  const savedAvatarUrl = savedFormData.profilePicture || `https://i.pravatar.cc/150?u=${currentUser?._id || 'default'}`
  const hasAvatarChanges = currentAvatarUrl !== savedAvatarUrl
  const activeEmailPreferenceCount = [formData.emailNotificationsMessages, formData.emailNotificationsConnections, formData.emailNotificationsProjects].filter(Boolean).length

  // Validate all form fields and return if valid
  const validateForm = () => {
    const newErrors = {}

    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required'
    }

    if (!formData.email.trim()) {
      newErrors.email = 'Email is required'
    } else if (!/^\S+@\S+\.\S+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email'
    }

    if (!formData.headline.trim()) {
      newErrors.headline = 'Professional headline is required'
    }

    if (!formData.skills.trim()) {
      newErrors.skills = 'Skills are required'
    }

    if (!formData.bio.trim()) {
      newErrors.bio = 'Bio is required'
    }

    if (!formData.servicesOffered.trim()) {
      newErrors.servicesOffered = 'Services offered is required'
    }

    if (formData.phone && !/^\+[0-9 ]{8,20}$/.test(formData.phone.replace(/_/g, ''))) {
      newErrors.phone = 'Please enter a valid phone number'
    }

    const numericFields = [
      { name: 'hourlyRate', label: 'Hourly rate' },
      { name: 'minimumProjectBudget', label: 'Minimum project budget' },
      { name: 'yearsOfExperience', label: 'Years of experience' }
    ]

    numericFields.forEach(({ name, label }) => {
      if (formData[name] !== '' && (Number.isNaN(Number(formData[name])) || Number(formData[name]) < 0)) {
        newErrors[name] = `${label} must be 0 or greater`
      }
    })

    const urlFields = ['website', 'github', 'linkedin', 'twitter', 'upworkProfile', 'fiverrProfile']
    urlFields.forEach((field) => {
      if (formData[field] && !/^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([/\w .-]*)*\/?$/.test(formData[field])) {
        newErrors[field] = 'Please enter a valid URL'
      }
    })

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Submit form data to API
  const handleSubmit = async (e) => {
    e.preventDefault()

    if (validateForm()) {
      setIsSubmitting(true)

      try {
        // Split fullName into firstName and lastName
        const nameParts = formData.fullName.split(' ')
        const firstName = nameParts[0] || ''
        const lastName = nameParts.slice(1).join(' ') || ''

        // Prepare the data for the API
        const profileData = {
          firstName,
          lastName,
          phone: formData.phone,
          location: formData.location,
          skills: formData.skills,
          bio: formData.bio,
          headline: formData.headline,
          availabilityStatus: formData.availabilityStatus,
          profileVisibility: formData.profileVisibility,
          responseTime: formData.responseTime,
          servicesOffered: formData.servicesOffered,
          tools: formData.tools,
          workPreference: formData.workPreference,
          yearsOfExperience: formData.yearsOfExperience === '' ? undefined : Number(formData.yearsOfExperience),
          minimumProjectBudget: formData.minimumProjectBudget === '' ? undefined : Number(formData.minimumProjectBudget),
          preferredProjectSize: formData.preferredProjectSize,
          preferredEngagements: formData.preferredEngagements
            .split(',')
            .map((item) => item.trim())
            .filter(Boolean),
          timezone: formData.timezone,
          availabilityDetails: formData.availabilityDetails,
          industries: formData.industries,
          showLocationPublic: formData.showLocationPublic,
          showHourlyRate: formData.showHourlyRate,
          allowDirectMessages: formData.allowDirectMessages,
          allowProjectInvites: formData.allowProjectInvites,
          emailNotificationsEnabled: formData.emailNotificationsEnabled,
          emailNotificationsMessages: formData.emailNotificationsMessages,
          emailNotificationsConnections: formData.emailNotificationsConnections,
          emailNotificationsProjects: formData.emailNotificationsProjects,
          website: formData.website,
          github: formData.github,
          linkedin: formData.linkedin,
          twitter: formData.twitter,
          profilePicture: formData.profilePicture,
          hourlyRate: formData.hourlyRate === '' ? undefined : Number(formData.hourlyRate),
          experienceLevel: formData.experienceLevel,
          languages: formData.languages,
          certifications: formData.certifications,
          serviceCategories: formData.serviceCategories,
          upworkProfile: formData.upworkProfile,
          fiverrProfile: formData.fiverrProfile
        }

        // Send profile update to API
        const response = await updateUserProfile(profileData)

        // Update the form state with the response to refresh the image display
        setFormData((prev) => {
          const nextFormData = {
            ...prev,
            profilePicture: response.profilePicture || prev.profilePicture
          }

          setSavedFormData(nextFormData)
          return nextFormData
        })

        setErrors({})
        toast.success('Changes saved successfully!')
      } catch (error) {
        const message = error.response?.data?.message || 'Failed to save changes. Please try again.'
        const validationErrors = error.response?.data?.errors

        if (validationErrors && typeof validationErrors === 'object') {
          const nextErrors = {}

          Object.entries(validationErrors).forEach(([field, details]) => {
            if (details?.message) {
              nextErrors[field] = details.message
            }
          })

          if (Object.keys(nextErrors).length > 0) {
            setErrors(nextErrors)
          }
        }

        toast.error(message)
      } finally {
        setIsSubmitting(false)
      }
    }
  }

  // Reset form to current user data or initial state
  const handleReset = () => {
    if (!hasUnsavedChanges) return

    if (currentUser) {
      populateFormWithUserData(currentUser)
    } else {
      setFormData(initialFormState)
      setSavedFormData(initialFormState)
      setIsLoading(false)
    }

    setErrors({})
    setIsSubmitting(false)
    toast.info('Form has been reset')
  }

  // Utility function for input field CSS classes
  const inputClasses = (errorField) => `
    w-full pl-10 p-3 rounded-lg
    theme-input theme-text
    transition-all duration-300
    border ${errors[errorField] ? 'border-red-500' : 'dark:border-light/10 border-primary/10'}
    dark:placeholder:text-light/40 placeholder:text-primary/40
    dark:focus:placeholder:text-light/60 focus:placeholder:text-primary/60
    focus:outline-none focus:ring-2 focus:ring-accent/50
  `
  const selectShellClasses = (errorField) => `
    relative rounded-lg
    bg-primary/15 dark:bg-light/12
    transition-all duration-300
    border ${errors[errorField] ? 'border-red-500' : 'border-primary/15 dark:border-light/10'}
    shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]
    hover:border-accent/35 hover:bg-primary/20 dark:hover:bg-light/15
    focus-within:border-accent/45
    focus-within:ring-2 focus-within:ring-accent/50
  `
  const selectFieldClasses = `
    w-full min-h-[50px] bg-transparent theme-text
    pl-10 pr-10 py-3 rounded-lg
    appearance-none theme-select
    focus:outline-none
  `
  const selectIconClasses = 'absolute left-3 top-1/2 -translate-y-1/2 text-accent text-[16px] pointer-events-none'
  const selectChevronClasses = 'absolute right-3 top-1/2 -translate-y-1/2 text-accent text-[14px] pointer-events-none'
  const toggleClasses = 'h-4 w-4 rounded border-primary/20 text-accent focus:ring-accent/50 dark:border-light/20 dark:bg-transparent'

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      {isLoading ? (
        <div className='flex justify-center items-center h-64'>
          <LoadingSpinner />
        </div>
      ) : (
        <>
          <motion.div className='mb-6 p-4 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700' initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
            <div className='flex items-center justify-between gap-4 flex-wrap'>
              <div>
                <p className='text-sm theme-text-secondary'>Profile completion</p>
                <p className='text-xl font-bold theme-text'>{profileCompleteness?.percentage ?? 0}%</p>
              </div>
              <div className='text-sm theme-text-secondary'>
                <p>Missing required: {missingRequired.length}</p>
                <p>Missing optional: {missingOptional.length}</p>
              </div>
            </div>

            <div className='flex items-center justify-between gap-4 flex-wrap'>
              {missingRequired.length > 0 && (
                <div className='mt-3'>
                  <p className='text-xs uppercase tracking-wide text-red-500 mb-1'>Required fields to complete</p>
                  <p className='text-sm theme-text-secondary'>{missingRequired.map((item) => item.label).join(', ')}</p>
                </div>
              )}
              <div className='text-sm theme-text-secondary'>
                <p className={hasUnsavedChanges ? 'text-amber-500' : 'theme-text-secondary'}>{hasUnsavedChanges ? 'Changes not saved yet' : 'Profile is up to date'}</p>
              </div>
            </div>
          </motion.div>

          <form onSubmit={handleSubmit}>
            <motion.div className='grid lg:grid-cols-2 gap-6 mb-8' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }}>
              {/* Basic Information */}
              <motion.div className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 h-full'>
                <h3 className='text-xl font-semibold theme-text mb-2'>Basic Information</h3>
                <p className='text-sm theme-text-secondary mb-4'>Details people use to recognize you and understand your background quickly.</p>
                <div className='grid gap-5'>
                  <div className='p-4 rounded-xl theme-input border theme-border'>
                    <div className='mb-4'>
                      <p className='text-xs uppercase tracking-wide theme-text-muted mb-2'>Identity</p>
                    </div>

                    <div className='space-y-5'>
                      <div className='flex flex-col items-center text-center p-4 rounded-xl bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700'>
                        <img key={currentAvatarUrl} src={currentAvatarUrl} alt='Profile' className='w-24 h-24 rounded-full border-2 border-gray-300 dark:border-gray-600 shadow-lg mb-4 object-cover' />

                        <div className='flex flex-wrap items-center justify-center gap-3'>
                          <motion.button
                            type='button'
                            onClick={() => {
                              const randomSeed = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15)
                              const newAvatarUrl = `https://i.pravatar.cc/150?u=${randomSeed}`
                              setFormData((prev) => ({ ...prev, profilePicture: newAvatarUrl }))
                            }}
                            className='flex items-center gap-2 bg-accent text-white px-4 py-2 rounded-lg hover:bg-accent/90 hover:shadow-lg transition-all duration-300'
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}>
                            <FaSyncAlt className='text-sm' />
                            <span className='text-sm font-medium'>Generate New Avatar</span>
                          </motion.button>

                          {hasAvatarChanges && (
                            <motion.button
                              type='button'
                              onClick={() =>
                                setFormData((prev) => ({
                                  ...prev,
                                  profilePicture: savedFormData.profilePicture
                                }))
                              }
                              className='px-4 py-2 rounded-lg border dark:border-light/10 border-primary/10 theme-text hover:text-accent hover:border-accent/40 hover:shadow-md transition-all duration-300'
                              whileHover={{ scale: 1.05 }}
                              whileTap={{ scale: 0.95 }}>
                              Use Current Avatar
                            </motion.button>
                          )}
                        </div>
                      </div>

                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Full Name</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaUser />
                          </span>
                          <input type='text' name='fullName' value={formData.fullName} onChange={handleChange} className={inputClasses('fullName')} placeholder='Enter your full name' />
                          {errors.fullName && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.fullName}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className='p-4 rounded-xl theme-input border theme-border'>
                    <div className='mb-4'>
                      <p className='text-xs uppercase tracking-wide theme-text-muted mb-2'>Contact</p>
                      <p className='text-sm theme-text-secondary'>Show the primary ways clients or collaborators can identify and reach you.</p>
                    </div>

                    <div className='space-y-4'>
                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Email</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaEnvelope />
                          </span>
                          <input
                            type='email'
                            name='email'
                            value={formData.email}
                            onChange={handleChange}
                            readOnly
                            className={`${inputClasses('email')} cursor-not-allowed opacity-80`}
                            placeholder='Enter your email address'
                          />
                          <p className='text-xs theme-text-muted mt-2'>Email changes require a separate verification flow and cannot be edited here.</p>
                          {errors.email && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.email}
                            </motion.p>
                          )}
                        </div>
                      </div>

                      <div>
                        <label className='block mb-2 theme-text-secondary text-sm'>Phone Number</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>
                            <FaPhone />
                          </span>
                          <input type='tel' name='phone' value={formData.phone} onChange={handleChange} className={inputClasses('phone')} placeholder='Enter your phone number' />
                          {errors.phone && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors.phone}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </motion.div>

              {/* Right Column: Public Presence */}
              <motion.div className='flex flex-col gap-6 h-full' initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.6, delay: 0.1 }}>
                <motion.div className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 flex-1'>
                  <h3 className='text-xl font-semibold theme-text mb-2'>Public Presence</h3>
                  <p className='text-sm theme-text-secondary mb-4'>Shape how people discover you, review your work, and understand your public profile at a glance.</p>
                  <div className='space-y-4'>
                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Professional Headline</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaBriefcase />
                        </span>
                        <input type='text' name='headline' value={formData.headline} onChange={handleChange} className={inputClasses('headline')} placeholder='Frontend developer focused on fast, polished client work' />
                        {errors.headline && (
                          <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                            {errors.headline}
                          </motion.p>
                        )}
                      </div>
                    </div>

                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Bio</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaBook />
                        </span>
                        <textarea
                          name='bio'
                          value={formData.bio}
                          onChange={handleChange}
                          className={inputClasses('bio')}
                          rows='4'
                          placeholder='Briefly describe your background, strengths, and the kind of work you do best'
                        />
                        {errors.bio && (
                          <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                            {errors.bio}
                          </motion.p>
                        )}
                      </div>
                    </div>

                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Location</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaMapMarkerAlt />
                        </span>
                        <input type='text' name='location' value={formData.location} onChange={handleChange} className={inputClasses('location')} placeholder='Enter your location' />
                      </div>
                    </div>
                    <div>
                      <label className='block mb-2 theme-text-secondary text-sm'>Timezone</label>
                      <div className='relative'>
                        <span className='absolute left-3 top-4 text-accent text-[16px]'>
                          <FaGlobe />
                        </span>
                        <input type='text' name='timezone' value={formData.timezone} onChange={handleChange} className={inputClasses('timezone')} placeholder='Europe/Vilnius' />
                      </div>
                    </div>
                    {[
                      { name: 'website', label: 'Portfolio', icon: <FaGlobe />, placeholder: 'Enter your portfolio URL' },
                      { name: 'github', label: 'GitHub', icon: <FaGithub />, placeholder: 'Enter your GitHub profile' },
                      { name: 'linkedin', label: 'LinkedIn', icon: <FaLinkedin />, placeholder: 'Enter your LinkedIn profile' },
                      { name: 'twitter', label: 'Twitter', icon: <FaTwitter />, placeholder: 'Enter your Twitter handle' }
                    ].map((social) => (
                      <div key={social.name}>
                        <label className='block mb-2 theme-text-secondary text-sm'>{social.label}</label>
                        <div className='relative'>
                          <span className='absolute left-3 top-4 text-accent text-[16px]'>{social.icon}</span>
                          <input type='url' name={social.name} value={formData[social.name]} onChange={handleChange} className={inputClasses(social.name)} placeholder={social.placeholder} />
                          {errors[social.name] && (
                            <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                              {errors[social.name]}
                            </motion.p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </motion.div>
              </motion.div>
            </motion.div>

            {showFreelancerSection && (
              <motion.div
                className='p-6 rounded-lg bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 mb-8'
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.65 }}>
                <h3 className='text-xl font-semibold theme-text mb-2'>Visibility & Contact Preferences</h3>
                <p className='text-sm theme-text-secondary mb-4'>Control what visitors can see and how clients are allowed to reach you.</p>

                <div className='grid gap-5'>
                  <div>
                    <label className='block mb-2 theme-text-secondary text-sm'>Profile Visibility</label>
                    <div className={selectShellClasses('profileVisibility')}>
                      <span className={selectIconClasses}>
                        <FaEye />
                      </span>
                      <select name='profileVisibility' value={formData.profileVisibility} onChange={handleChange} className={selectFieldClasses}>
                        <option value='public'>Public</option>
                        <option value='members'>Members only</option>
                        <option value='private'>Private</option>
                      </select>
                      <span className={selectChevronClasses}>
                        <FaChevronDown />
                      </span>
                    </div>
                    <p className='text-xs theme-text-muted mt-2'>Choose who can view your full profile details on the platform.</p>
                  </div>

                  <div className='grid md:grid-cols-2 gap-4'>
                    <label className='flex items-start gap-3 p-4 rounded-xl theme-input border theme-border cursor-pointer hover:border-accent/30 hover:shadow-md transition-all duration-300'>
                      <input type='checkbox' name='showLocationPublic' checked={formData.showLocationPublic} onChange={handleChange} className={toggleClasses} />
                      <div>
                        <p className='text-sm font-medium theme-text'>Show location publicly</p>
                        <p className='text-xs theme-text-muted mt-1'>Let visitors see your location on the public profile.</p>
                      </div>
                    </label>

