import { useState } from 'react'
import PropTypes from 'prop-types'
import { motion } from 'framer-motion'
import { FaLock, FaEye, FaEyeSlash } from 'react-icons/fa'
import { toast } from 'react-toastify'
import LoadingSpinner from '../shared/LoadingSpinner'
import { changeUserPassword } from '../../services/userService'

const SecuritySettings = () => {
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  })

  const [showPasswords, setShowPasswords] = useState({
    currentPassword: false,
    newPassword: false,
    confirmPassword: false
  })

  const [errors, setErrors] = useState({})
  const [passwordStrength, setPasswordStrength] = useState(0)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [passwordUpdated, setPasswordUpdated] = useState(false)
  const [sessionExpired, setSessionExpired] = useState(false)

  const validateForm = () => {
    const newErrors = {}

    // Current password validation
    if (!passwordData.currentPassword.trim()) {
      newErrors.currentPassword = 'Current password is required'
    }

    // New password validation
    if (!passwordData.newPassword) {
      newErrors.newPassword = 'New password is required'
    } else {
      // Password strength rules
      if (passwordData.newPassword.length < 8) {
        newErrors.newPassword = 'Password must be at least 8 characters'
      }
      if (!/[A-Z]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one uppercase letter'
      }
      if (!/[a-z]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one lowercase letter'
      }
      if (!/[0-9]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one number'
      }
      if (!/[!@#$%^&*]/.test(passwordData.newPassword)) {
        newErrors.newPassword = 'Password must contain at least one special character'
      }
    }

    if (passwordData.currentPassword && passwordData.newPassword && passwordData.currentPassword === passwordData.newPassword) {
      newErrors.newPassword = 'New password must be different from current password'
    }

    // Confirm password validation
    if (!passwordData.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your new password'
    } else if (passwordData.newPassword !== passwordData.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // Each criteria adds 20% to strength
  const calculatePasswordStrength = (password) => {
    let strength = 0
    if (password.length >= 8) strength += 20
    if (/[A-Z]/.test(password)) strength += 20
    if (/[a-z]/.test(password)) strength += 20
    if (/[0-9]/.test(password)) strength += 20
    if (/[!@#$%^&*]/.test(password)) strength += 20
    return strength
  }

  // Random password generator
  const generateStrongPassword = () => {
    const lowercase = 'abcdefghijklmnopqrstuvwxyz'
    const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    const numbers = '0123456789'
    const symbols = '!@#$%^&*'

    if (passwordUpdated) {
      setPasswordUpdated(false)
    }

    if (sessionExpired) {
      setSessionExpired(false)
    }

    const getRandomChar = (str) => str.charAt(Math.floor(Math.random() * str.length))

    let password = [getRandomChar(lowercase), getRandomChar(uppercase), getRandomChar(numbers), getRandomChar(symbols)]

    const allChars = lowercase + uppercase + numbers + symbols
    for (let i = password.length; i < 12; i++) {
      password.push(getRandomChar(allChars))
    }

    password = password.sort(() => Math.random() - 0.5)

    const newPassword = password.join('')

    setPasswordData((prev) => ({
      ...prev,
      newPassword,
      confirmPassword: ''
    }))

    setErrors((prev) => {
      const nextErrors = { ...prev }
      delete nextErrors.newPassword
      delete nextErrors.confirmPassword

      if (passwordData.currentPassword !== newPassword) {
        delete nextErrors.newPassword
      }

      return nextErrors
    })

    setPasswordStrength(calculatePasswordStrength(newPassword))
  }

  // Password requirements
  const PasswordRequirements = ({ password }) => {
    const requirements = [
      { label: 'At least 8 characters', test: (pwd) => pwd.length >= 8 },
      { label: 'Contains uppercase letter', test: (pwd) => /[A-Z]/.test(pwd) },
      { label: 'Contains lowercase letter', test: (pwd) => /[a-z]/.test(pwd) },
      { label: 'Contains number', test: (pwd) => /[0-9]/.test(pwd) },
      { label: 'Contains special character', test: (pwd) => /[!@#$%^&*]/.test(pwd) }
    ]

    return (
      <div className='mt-2 space-y-2'>
        {requirements.map((req, index) => (
          <motion.div key={index} className='flex items-center space-x-2' initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: index * 0.1 }}>
            <span className={`text-sm ${req.test(password) ? 'text-green-500' : 'text-red-500'}`}>{req.test(password) ? 'Γ£ô' : '├ù'}</span>
            <span className='text-sm theme-text-secondary'>{req.label}</span>
          </motion.div>
        ))}
      </div>
    )
  }

  PasswordRequirements.propTypes = {
    password: PropTypes.string.isRequired
  }

  // Updates strength when password changes
  const handleChange = (e) => {
    const { name, value } = e.target

    if (passwordUpdated) {
      setPasswordUpdated(false)
    }

    if (sessionExpired) {
      setSessionExpired(false)
    }

    setPasswordData((prev) => {
      const nextPasswordData = {
        ...prev,
        [name]: value
      }

      setErrors((prevErrors) => {
        const nextErrors = {
          ...prevErrors
        }

        delete nextErrors[name]

        if (name === 'currentPassword' || name === 'newPassword') {
          if (nextPasswordData.currentPassword !== nextPasswordData.newPassword) {
            delete nextErrors.newPassword
          }
        }

        if (name === 'newPassword' || name === 'confirmPassword') {
          if (nextPasswordData.newPassword === nextPasswordData.confirmPassword) {
            delete nextErrors.confirmPassword
          }
        }

        return nextErrors
      })

      return nextPasswordData
    })

    if (name === 'newPassword') {
      setPasswordStrength(calculatePasswordStrength(value))
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!validateForm()) return

    try {
      setIsSubmitting(true)
      setSessionExpired(false)

      const response = await changeUserPassword({
        currentPassword: passwordData.currentPassword,
        newPassword: passwordData.newPassword
      })

      toast.success(response.message || 'Password updated successfully.')

      setPasswordData({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      })
      setErrors({})
      setPasswordStrength(0)
      setPasswordUpdated(true)
      setShowPasswords({
        currentPassword: false,
        newPassword: false,
        confirmPassword: false
      })
    } catch (error) {
      const status = error.response?.status
      const message = error.response?.data?.message || 'Failed to update password.'
      setPasswordUpdated(false)

      if (status === 401) {
        setSessionExpired(true)
        toast.error('Your session has expired. Please sign in again before updating your password.')
        return
      }

      toast.error(message)

      if (message.toLowerCase().includes('current password')) {
        setErrors((prev) => ({
          ...prev,
          currentPassword: message
        }))
      }

      if (message.toLowerCase().includes('new password')) {
        setErrors((prev) => ({
          ...prev,
          newPassword: message
        }))
      }
    } finally {
      setIsSubmitting(false)
    }
  }

  const getInputClasses = (fieldName) => `
  w-full pl-10 p-3 rounded-lg
  theme-input theme-text
  transition-all duration-300
  border ${errors[fieldName] ? 'border-red-500' : 'dark:border-light/10 border-primary/10'}
  dark:placeholder:text-light/40 placeholder:text-primary/40
  dark:focus:placeholder:text-light/60 focus:placeholder:text-primary/60
  focus:outline-none focus:ring-2 focus:ring-accent/50
`

  const hasUppercase = /[A-Z]/.test(passwordData.newPassword)
  const hasLowercase = /[a-z]/.test(passwordData.newPassword)
  const hasNumber = /[0-9]/.test(passwordData.newPassword)
  const hasSpecialCharacter = /[!@#$%^&*]/.test(passwordData.newPassword)
  const hasMinimumLength = passwordData.newPassword.length >= 8
  const isNewPasswordDifferent = Boolean(passwordData.currentPassword && passwordData.newPassword && passwordData.currentPassword !== passwordData.newPassword)
  const doPasswordsMatch = Boolean(passwordData.newPassword && passwordData.confirmPassword && passwordData.newPassword === passwordData.confirmPassword)
  const hasStartedPasswordFlow = Boolean(passwordData.currentPassword || passwordData.newPassword || passwordData.confirmPassword)
  const canSubmitPassword = Boolean(
    passwordData.currentPassword &&
    passwordData.newPassword &&
    passwordData.confirmPassword &&
    hasMinimumLength &&
    hasUppercase &&
    hasLowercase &&
    hasNumber &&
    hasSpecialCharacter &&
    isNewPasswordDifferent &&
    doPasswordsMatch
  )

  return (
    <motion.div className='space-y-8' initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
      <motion.div
        className='p-6 rounded-lg bg-gradient-to-br dark:from-light/10 dark:to-light/5 from-primary/10 to-primary/5 border theme-border'
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}>
        <h3 className='text-xl font-semibold theme-text mb-2'>Change Password</h3>
        <p className='text-sm theme-text-secondary mb-2'>Use a strong password you do not reuse elsewhere to keep your account protected.</p>
        <p className='text-xs theme-text-muted mb-4'>Your current password is required before a new one can be saved.</p>

        <form onSubmit={handleSubmit} className='space-y-6'>
          <div>
            <p className='text-xs uppercase tracking-wide theme-text-muted mb-4'>Verification</p>
            <div>
              <label className='block mb-2 theme-text-secondary text-sm'>Current Password</label>
              <div className='relative'>
                <span className='absolute left-3 top-4 text-accent text-[16px]'>
                  <FaLock />
                </span>
                <input
                  type={showPasswords.currentPassword ? 'text' : 'password'}
                  name='currentPassword'
                  value={passwordData.currentPassword}
                  onChange={handleChange}
                  className={getInputClasses('currentPassword')}
                  placeholder='Enter current password'
                />
                <button
                  type='button'
                  onClick={() =>
                    setShowPasswords((prev) => ({
                      ...prev,
                      currentPassword: !prev.currentPassword
                    }))
                  }
                  className='absolute right-3 top-4 text-accent text-[16px]'>
                  {showPasswords.currentPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
                {errors.currentPassword && (
                  <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                    {errors.currentPassword}
                  </motion.p>
                )}
              </div>
            </div>

            <div className='pt-2 border-t dark:border-light/10 border-primary/10'>
              <p className='text-xs uppercase tracking-wide theme-text-muted mb-4'>New Password</p>

              <div className='space-y-6'>
                <div>
                  <label className='block mb-2 theme-text-secondary text-sm'>New Password</label>
                  <div className='relative'>
                    <span className='absolute left-3 top-4 text-accent text-[16px]'>
                      <FaLock />
                    </span>
                    <input
                      type={showPasswords.newPassword ? 'text' : 'password'}
                      name='newPassword'
                      value={passwordData.newPassword}
                      onChange={handleChange}
                      className={getInputClasses('newPassword')}
                      placeholder='Enter new password'
                    />
                    <button
                      type='button'
                      onClick={() =>
                        setShowPasswords((prev) => ({
                          ...prev,
                          newPassword: !prev.newPassword
                        }))
                      }
                      className='absolute right-3 top-4 text-accent text-[16px]'>
                      {showPasswords.newPassword ? <FaEyeSlash /> : <FaEye />}
                    </button>
                    {errors.newPassword && (
                      <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                        {errors.newPassword}
                      </motion.p>
                    )}
                  </div>

                  <div className='mt-3 flex items-center justify-between gap-3 flex-wrap'>
                    <p className='text-xs theme-text-muted'>Need help? Generate a strong password and store it in your password manager.</p>
                    <button
                      type='button'
                      onClick={generateStrongPassword}
                      className='inline-flex items-center gap-2 px-3 py-1.5 rounded-lg border dark:border-light/10 border-primary/10 theme-text hover:text-accent hover:border-accent/40 transition-colors'>
                      Generate Strong Password
                    </button>
                  </div>

                  {passwordData.newPassword ? (
                    <>
                      <div className='mt-3'>
                        <div className='h-2 w-full rounded-full overflow-hidden bg-primary/10 dark:bg-light/10'>
                          <motion.div
                            className={`h-full ${passwordStrength <= 40 ? 'bg-red-500' : passwordStrength <= 80 ? 'bg-yellow-500' : 'bg-green-500'}`}
                            initial={{ width: 0 }}
                            animate={{ width: `${passwordStrength}%` }}
                            transition={{ duration: 0.3 }}
                          />
                        </div>
                        <p className='text-sm mt-1 theme-text-secondary'>Password Strength: {passwordStrength <= 40 ? 'Weak' : passwordStrength <= 80 ? 'Medium' : 'Strong'}</p>
                      </div>

                      <PasswordRequirements password={passwordData.newPassword} />
                    </>
                  ) : (
                    <p className='text-sm theme-text-secondary mt-3'>Start typing a new password to see strength feedback and requirements.</p>
                  )}
                </div>

                <div>
                  <label className='block mb-2 theme-text-secondary text-sm'>Confirm Password</label>
                  <div className='relative'>
                    <span className='absolute left-3 top-4 text-accent text-[16px]'>
                      <FaLock />
                    </span>
                    <input
                      type={showPasswords.confirmPassword ? 'text' : 'password'}
                      name='confirmPassword'
                      value={passwordData.confirmPassword}
                      onChange={handleChange}
                      className={getInputClasses('confirmPassword')}
                      placeholder='Confirm new password'
                    />
                    <button
                      type='button'
                      onClick={() =>
                        setShowPasswords((prev) => ({
                          ...prev,
                          confirmPassword: !prev.confirmPassword
                        }))
                      }
                      className='absolute right-3 top-4 text-accent text-[16px]'>
                      {showPasswords.confirmPassword ? <FaEyeSlash /> : <FaEye />}
                    </button>
                    {errors.confirmPassword && (
                      <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className='text-red-500 text-sm mt-1'>
                        {errors.confirmPassword}
                      </motion.p>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className='space-y-3'>
            {sessionExpired && (
              <motion.p initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className='text-sm text-amber-600 dark:text-amber-400'>
                Your session expired before the password update completed. Sign in again, then retry this form.
              </motion.p>
            )}
            {passwordUpdated && (
              <motion.p initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className='text-sm text-green-600 dark:text-green-400'>
                Password updated successfully. Use your new password the next time you sign in.
              </motion.p>
            )}
            <p className='text-sm theme-text-secondary'>
              {!hasStartedPasswordFlow
                ? 'Enter your current and new password to begin.'
                : isSubmitting
                  ? 'Updating your password now.'
                  : !canSubmitPassword
                    ? 'Complete all requirements and make sure both new password fields match before submitting.'
                    : 'Your password details are ready to submit.'}
            </p>

            <motion.button
              type='submit'
              className='w-full bg-accent text-white font-medium py-3 px-6 rounded-lg
              hover:bg-accent/90 transition-colors duration-300
              focus:outline-none focus:ring-2 focus:ring-accent/50
              disabled:opacity-50 disabled:cursor-not-allowed
              flex items-center justify-center gap-2'
              whileHover={canSubmitPassword && !isSubmitting ? { scale: 1.02 } : undefined}
              whileTap={canSubmitPassword && !isSubmitting ? { scale: 0.98 } : undefined}
              disabled={!canSubmitPassword || isSubmitting}>
              {isSubmitting && <LoadingSpinner size='sm' className='border-t-2 border-white' />}
              {isSubmitting ? 'Updating Password...' : 'Update Password'}
            </motion.button>
          </div>
        </form>
      </motion.div>
    </motion.div>
  )
}

export default SecuritySettings

import { useState, useEffect } from 'react'
import PropTypes from 'prop-types'
import { motion, AnimatePresence } from 'framer-motion'
import { FaWindowMaximize, FaWindowMinimize } from 'react-icons/fa'
import { toast } from 'react-toastify'
import AvailabilityCalendarSkeleton from './AvailabilityCalendarSkeleton'

const AvailabilityCalendar = ({ freelancerId, isOwnProfile = false, isPublicView = true }) => {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [hoveredDay, setHoveredDay] = useState(null)
  const [editMode, setEditMode] = useState(false)
  const [selectedDays, setSelectedDays] = useState({})
  const [saving, setSaving] = useState(false)
  const [togglingVisibility, setTogglingVisibility] = useState(false)
  const [statusFilter, setStatusFilter] = useState(null)
  const [filterLoading, setFilterLoading] = useState(false)
  const [viewMode, setViewMode] = useState('detailed') // 'compact' or 'detailed'

  const {
    calendarData,
    loading,
    error,
    isPublic,
    optimisticUpdates,
    fetchCalendarData,
    fetchFilteredCalendarData,
    updateMultipleDays,
    toggleVisibility,
    applyOptimisticUpdate,
    rollbackOptimisticUpdate,
    clearOptimisticUpdates
  } = useAvailability(freelancerId, isPublicView)

  // Guard: Don't render if no freelancerId
  if (!freelancerId) {
    return <div className='p-4 text-center theme-text-secondary'>No freelancer ID provided</div>
  }

  // Fetch calendar data when component mounts or freelancerId changes
  useEffect(() => {
    const year = currentDate.getFullYear()
    const month = currentDate.getMonth() + 1
    fetchCalendarData(year, month).catch((err) => {
      console.error('Failed to fetch calendar on mount:', err)
    })
  }, [currentDate, freelancerId, fetchCalendarData])

  const getStatusColor = (status) => {
    const colorMap = {
      red: '#ef4444',
      orange: '#f97316',
      yellow: '#eab308',
      green: '#22c55e'
    }
    return colorMap[status] || '#e5e7eb'
  }

  const getStatusLabel = (status) => {
    const labelMap = {
      red: '100% Busy',
      orange: '50% Busy',
      yellow: 'Partially Busy',
      green: 'Available'
    }
    return labelMap[status] || 'Unknown'
  }

  const VALID_STATUSES = ['green', 'yellow', 'orange', 'red']

  const isValidStatus = (status) => {
    return VALID_STATUSES.includes(status)
  }

  const isValidDateKey = (dateKey) => {
    const [year, month, date] = dateKey.split('-').map(Number)
    if (!year || !month || !date) return false
    if (month < 1 || month > 12) return false
    if (date < 1 || date > 31) return false

    const selectedDate = new Date(year, month - 1, date)
    const isValidDate = selectedDate.getFullYear() === year && selectedDate.getMonth() === month - 1 && selectedDate.getDate() === date

    return isValidDate
  }

  const canModifyDate = (dateKey) => {
    const [year, month, date] = dateKey.split('-').map(Number)
    const selectedDate = new Date(year, month - 1, date)
    const today = new Date()
    today.setHours(0, 0, 0, 0)

    return selectedDate >= today
  }

  const getDayCapacityLabel = (capacity) => {
    if (capacity === 100) return 'Fully Available'
    if (capacity >= 50) return `${capacity}% Available`
    if (capacity > 0) return `${capacity}% Available (Limited)`
    return 'Fully Booked'
  }

  const previousMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1))
  }

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1))
  }

  const handleDayClick = (day) => {
    if (!editMode || !day?.date) return

    const dateKey = `${calendarData.year}-${calendarData.month}-${day?.date}`

    if (!canModifyDate(dateKey)) {
      toast.error('Cannot modify past dates')
      return
    }

    const rest = Object.fromEntries(Object.entries(selectedDays).filter(([key]) => key !== dateKey))
    if (selectedDays[dateKey]) {
      setSelectedDays(rest)
    } else {
      setSelectedDays({
        ...selectedDays,
        [dateKey]: day?.status
      })
    }
  }

  const handleStatusChange = (dateKey, newStatus) => {
    if (!isValidStatus(newStatus)) {
      toast.error('Invalid status selected')
      console.error(`Invalid status: ${newStatus}`)
      return
    }

    if (!isValidDateKey(dateKey)) {
      toast.error('Invalid date key')
      console.error(`Invalid date key: ${dateKey}`)
      return
    }

    setSelectedDays({
      ...selectedDays,
      [dateKey]: newStatus
    })
  }

  const handleSaveChanges = async () => {
    if (Object.keys(selectedDays).length === 0) {
      toast.info('No changes to save')
      return
    }

    // Validate all selected days before saving
    const invalidDays = Object.entries(selectedDays).filter(([dateKey, status]) => {
      if (!isValidDateKey(dateKey)) {
        console.error(`Invalid date key format: ${dateKey}`)
        return true
      }
      if (!isValidStatus(status)) {
        console.error(`Invalid status: ${status}`)
        return true
      }
      if (!canModifyDate(dateKey)) {
        console.error(`Cannot modify past date: ${dateKey}`)
        return true
      }
      return false
    })

    if (invalidDays.length > 0) {
      toast.error(`Cannot modify ${invalidDays.length} day(s). Check console for details.`)
      return
    }

    setSaving(true)

    try {
      // Apply optimistic updates
      Object.entries(selectedDays).forEach(([dateKey, status]) => {
        applyOptimisticUpdate(dateKey, status)
      })

      // Convert selectedDays to updates format for the hook
      const updates = Object.entries(selectedDays).map(([dateKey, status]) => {
        const [year, month, date] = dateKey.split('-')
        return { year: parseInt(year), month: parseInt(month), date: parseInt(date), status }
      })

      const { failures } = await updateMultipleDays(updates)

      if (failures.length > 0) {
        // Rollback failed updates
        failures.forEach(({ year, month, date }) => {
          const dateKey = `${year}-${month}-${date}`
          rollbackOptimisticUpdate(dateKey)
        })
        toast.error(`Failed to update ${failures.length} day(s)`)
      } else {
        toast.success('Availability updated successfully')
        clearOptimisticUpdates()
      }

      setEditMode(false)
      setSelectedDays({})

      // Refresh calendar
      const year = currentDate.getFullYear()
      const month = currentDate.getMonth() + 1
      await fetchCalendarData(year, month)
    } catch (err) {
      // Rollback all optimistic updates on critical error
      clearOptimisticUpdates()
      toast.error(`Error updating availability: ${err.message}`)
      console.error('Error saving changes:', err)
    } finally {
      setSaving(false)
    }
  }

  const handleCancel = () => {
    setEditMode(false)
    setSelectedDays({})
  }

  const handleToggleVisibility = async () => {
    setTogglingVisibility(true)
    try {
      const newVisibility = await toggleVisibility()
      toast.success(`Calendar is now ${newVisibility ? 'public' : 'private'}`)
    } catch (err) {
      toast.error(`Error updating visibility: ${err.message}`)
      console.error('Error toggling visibility:', err)
    } finally {
      setTogglingVisibility(false)
    }
  }

  const handleStatusFilterChange = async (status) => {
    setStatusFilter(status)
    setFilterLoading(true)

    try {
      const year = currentDate.getFullYear()
      const month = currentDate.getMonth() + 1
      await fetchFilteredCalendarData(year, month, status)
    } catch (err) {
      console.error('Error applying filter:', err)
      toast.error('Error applying filter')
    } finally {
      setFilterLoading(false)
    }
  }

  const handleClearFilter = async () => {
    setStatusFilter(null)
    setFilterLoading(true)

    try {
      const year = currentDate.getFullYear()
      const month = currentDate.getMonth() + 1
      await fetchCalendarData(year, month)
    } catch (err) {
      console.error('Error clearing filter:', err)
    } finally {
      setFilterLoading(false)
    }
  }

  if (loading) {
    return <AvailabilityCalendarSkeleton />
  }

  if (error) {
    return (
      <div className='p-4 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg'>
        <p className='text-red-700 dark:text-red-400'>Error loading calendar: {error}</p>
      </div>
    )
  }

  if (!calendarData || !calendarData.days) {
    return <div className='p-4 text-center theme-text-secondary'>No calendar data available</div>
  }

  return (
    <div className='space-y-4 my-0 pb-6'>
      {/* View Toggle Button */}
      <div className='flex justify-end gap-2 px-6 mt-6'>
        <motion.button
          onClick={() => setViewMode('compact')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`px-3 py-2 rounded-lg transition-all duration-200 flex items-center gap-2 text-sm font-medium ${
            viewMode === 'compact' ? 'bg-accent text-white shadow-lg' : 'bg-primary/10 dark:bg-light/10 theme-text hover:shadow hover:bg-primary/20 dark:hover:bg-light/20'
          }`}
          aria-label='Switch to compact view'
          title='Compact view'>
          <FaWindowMinimize className='text-xs' />
          <span className='hidden sm:inline'>Compact</span>
        </motion.button>
        <motion.button
          onClick={() => setViewMode('detailed')}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`px-3 py-2 rounded-lg transition-all duration-200 flex items-center gap-2 text-sm font-medium ${
            viewMode === 'detailed' ? 'bg-accent text-white shadow-lg' : 'bg-primary/10 dark:bg-light/10 theme-text hover:shadow hover:bg-primary/20 dark:hover:bg-light/20'
          }`}
          aria-label='Switch to detailed view'
          title='Detailed view'>
          <FaWindowMaximize className='text-xs' />
          <span className='hidden sm:inline'>Detailed</span>
        </motion.button>
      </div>

      {/* Calendar View */}
      <AnimatePresence mode='wait'>
        {viewMode === 'compact' ? (
          <motion.div key='compact' initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className='px-6 mb-6'>
            <CompactCalendarView
              calendarData={calendarData}
              currentDate={currentDate}
              onPreviousMonth={previousMonth}
              onNextMonth={nextMonth}
              getStatusColor={getStatusColor}
              getStatusLabel={getStatusLabel}
              getDayCapacityLabel={getDayCapacityLabel}
            />
          </motion.div>
        ) : (
          <motion.div key='detailed' initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className='px-6 mb-6'>
            <DetailedCalendarView
              calendarData={calendarData}
              currentDate={currentDate}
              isOwnProfile={isOwnProfile}
              isPublicView={isPublicView}
              isPublic={isPublic}
              editMode={editMode}
              selectedDays={selectedDays}
              saving={saving}
              togglingVisibility={togglingVisibility}
              statusFilter={statusFilter}
              filterLoading={filterLoading}
              optimisticUpdates={optimisticUpdates}
              hoveredDay={hoveredDay}
              onPreviousMonth={previousMonth}
              onNextMonth={nextMonth}
              onEditMode={() => setEditMode(true)}
              onHandleToggleVisibility={handleToggleVisibility}
              onStatusFilterChange={handleStatusFilterChange}
              onClearFilter={handleClearFilter}
              onDayClick={handleDayClick}
              onStatusChange={handleStatusChange}
              onSaveChanges={handleSaveChanges}
              onCancel={handleCancel}
              onHoveredDay={setHoveredDay}
              getStatusColor={getStatusColor}
              getStatusLabel={getStatusLabel}
              getDayCapacityLabel={getDayCapacityLabel}
            />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

AvailabilityCalendar.propTypes = {
  freelancerId: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  isOwnProfile: PropTypes.bool,
  isPublicView: PropTypes.bool
}

export default AvailabilityCalendar

import { motion, AnimatePresence } from 'framer-motion'
import PropTypes from 'prop-types'
import { FaChevronLeft, FaChevronRight, FaEdit, FaCheck, FaEye, FaEyeSlash, FaSpinner } from 'react-icons/fa'
import AvailabilityEditPanel from './AvailabilityEditPanel'

const DetailedCalendarView = ({
  calendarData,
  isOwnProfile,
  isPublicView,
  isPublic,
  editMode,
  selectedDays,
  saving,
  togglingVisibility,
  statusFilter,
  filterLoading,
  optimisticUpdates,
  hoveredDay,
  onPreviousMonth,
  onNextMonth,
  onEditMode,
  onHandleToggleVisibility,
  onStatusFilterChange,
  onClearFilter,
  onDayClick,
  onStatusChange,
  onSaveChanges,
  onCancel,
  onHoveredDay,
  getStatusColor,
  getStatusLabel,
  getDayCapacityLabel
}) => {
  if (!calendarData || !calendarData.days) {
    return <div className='p-4 text-center theme-text-secondary'>No calendar data available</div>
  }

  const monthName = new Date(calendarData.year, calendarData.month - 1).toLocaleString('default', {
    month: 'long',
    year: 'numeric'
  })
  // Convert to Monday-first calendar (0 = Monday, 6 = Sunday)
  const firstDayOfMonth = (new Date(calendarData.year, calendarData.month - 1, 1).getDay() + 6) % 7
  const calendarGrid = [...Array(firstDayOfMonth), ...calendarData.days]

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className='p-6 bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent rounded-lg border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
      {/* Header */}
      <div className='flex items-center justify-between mb-7'>
        <h3 className='text-lg font-semibold theme-text'>{monthName}</h3>
        <div className='flex gap-2 items-center'>
          <motion.button onClick={onPreviousMonth} whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }} className='p-2 hover:bg-accent/10 rounded-lg transition-colors duration-200' aria-label='Previous month'>
            <FaChevronLeft className='theme-text' />
          </motion.button>
          <motion.button onClick={onNextMonth} whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.95 }} className='p-2 hover:bg-accent/10 rounded-lg transition-colors duration-200' aria-label='Next month'>
            <FaChevronRight className='theme-text' />
          </motion.button>
          {isOwnProfile && !editMode && (
            <>
              <motion.button
                onClick={onEditMode}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className='p-2 hover:bg-accent/10 rounded-lg transition-colors duration-200 text-accent'
                aria-label='Edit availability'>
                <FaEdit />
              </motion.button>
              <motion.button
                onClick={onHandleToggleVisibility}
                disabled={togglingVisibility}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className='p-2 hover:bg-accent/10 rounded-lg transition-colors duration-200 text-accent disabled:opacity-50'
                title={isPublic ? 'Make calendar private' : 'Make calendar public'}
                aria-label='Toggle calendar visibility'>
                {togglingVisibility ? <FaSpinner className='animate-spin' /> : isPublic ? <FaEye /> : <FaEyeSlash />}
              </motion.button>
            </>
          )}
        </div>
      </div>

      {/* Edit Mode Banner */}
      {editMode && (
        <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className='mb-4 p-4 bg-accent/10 border border-accent/30 rounded-lg theme-text-secondary text-sm font-medium'>
          Click on a day to select it, then choose its status. {Object.keys(selectedDays).length} day(s) selected.
        </motion.div>
      )}

      {/* Legend */}
      <div className='grid grid-cols-2 md:grid-cols-4 gap-3 mb-6'>
        {[
          { status: 'green', label: 'Available', capacity: '100%' },
          { status: 'yellow', label: 'Partially Busy', capacity: '1-50%' },
          { status: 'orange', label: '50% Busy', capacity: '50-99%' },
          { status: 'red', label: '100% Busy', capacity: '0%' }
        ].map((item) => (
          <motion.div
            key={item.status}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className='p-3 rounded-lg bg-gradient-to-br dark:from-light/5 dark:via-light/[0.02] from-primary/5 via-primary/[0.02] to-transparent border border-primary/10 dark:border-light/10 backdrop-blur-sm'>
            <div className='flex items-center gap-3'>
              <div className='w-4 h-4 md:w-5 md:h-5 rounded flex-shrink-0' style={{ backgroundColor: getStatusColor(item.status) }}></div>
              <div className='flex flex-col min-w-0'>
                <span className='theme-text text-xs md:text-sm font-medium'>{item.label}</span>
                <span className='theme-text-secondary text-xs opacity-70'>{item.capacity}</span>
              </div>
            </div>
          </motion.div>
        ))}
      </div>

      {/* Status Filter - only for own profile */}
      {isOwnProfile && !editMode && (
        <div className='mb-6 pb-6 border-b border-primary/10 dark:border-light/10'>
          <StatusFilterChips selectedStatus={statusFilter} onStatusChange={onStatusFilterChange} onClear={onClearFilter} />
          {filterLoading && (
            <div className='mt-3 flex items-center gap-2 text-sm theme-text-secondary'>
              <div className='animate-spin'>
                <div className='w-4 h-4 border-2 border-accent border-t-transparent rounded-full'></div>
              </div>
              <span>Filtering calendar...</span>
            </div>
          )}
        </div>
      )}

      {/* Day headers */}
      <div className='grid grid-cols-7 gap-1 mb-3'>
        {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day) => (
          <div key={day} className='text-center text-xs md:text-sm font-semibold theme-text-secondary py-2 md:py-3'>
            <span className='hidden sm:inline'>{day}</span>
            <span className='sm:hidden'>{day.slice(0, 1)}</span>
          </div>
        ))}
      </div>

      {/* Calendar Grid - Responsive */}
      <div className='grid grid-cols-7 gap-1'>
        <AnimatePresence>
          {calendarGrid?.map((day, idx) => {
            const isEmpty = !day?.date
            const isToday = !isEmpty && new Date(calendarData.year, calendarData.month - 1, day?.date).toDateString() === new Date().toDateString()
            const dateKey = `${calendarData.year}-${calendarData.month}-${day?.date}`
            const isSelected = selectedDays[dateKey]
            const currentStatus = optimisticUpdates[dateKey] || isSelected || day?.status

            return (
              <motion.div
                key={`${calendarData.month}-${idx}`}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: idx * 0.02 }}
                onMouseEnter={() => !isEmpty && onHoveredDay(idx)}
                onMouseLeave={() => onHoveredDay(null)}
                onClick={() => onDayClick(day)}
                className={`relative aspect-square rounded-lg flex flex-col items-center justify-center transition-all duration-200 cursor-pointer text-xs md:text-sm ${
                  !isEmpty && editMode ? 'hover:shadow-lg hover:scale-110 ring-2' : !isEmpty ? 'hover:shadow-lg hover:scale-105' : ''
                } ${isSelected ? 'ring-4 ring-blue-500' : editMode && !isEmpty ? 'ring-2 ring-gray-300 dark:ring-gray-600' : ''}`}
                style={{
                  backgroundColor: isEmpty ? 'transparent' : getStatusColor(currentStatus)
                }}>
                {!isEmpty && (
                  <>
                    {/* Day number */}
                    <span className={`font-semibold ${['red', 'orange'].includes(currentStatus) ? 'text-white' : 'text-gray-900 dark:text-white'}`}>{day.date}</span>

                    {/* Capacity indicator bar */}
                    {day.capacity < 100 && (
                      <div className='absolute bottom-1 left-1 right-1 h-1 bg-gray-300 dark:bg-gray-600 rounded-full overflow-hidden'>
                        <div className='h-full bg-green-500 transition-all' style={{ width: `${100 - day.capacity}%` }} />
                      </div>
                    )}

                    {/* Today indicator */}
                    {isToday && <div className='absolute inset-0 rounded-lg border-2 border-white dark:border-gray-900 opacity-60'></div>}

                    {/* Selected indicator */}
                    {isSelected && (
                      <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className='absolute top-1 right-1 w-3 h-3 md:w-4 md:h-4 bg-blue-500 rounded-full flex items-center justify-center'>
                        <FaCheck className='text-white text-xs' />
                      </motion.div>
                    )}

                    {/* Project count badge */}
                    {!isSelected && day.projectsCount > 0 && (
                      <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className='absolute top-1 right-1 w-5 h-5 md:w-6 md:h-6 bg-accent rounded-full flex items-center justify-center'>
                        <span className='text-white text-xs font-bold'>{day.projectsCount}</span>
                      </motion.div>
                    )}

                    {/* Hover tooltip - hidden on mobile */}
                    <AnimatePresence>
                      {hoveredDay === idx && (
                        <motion.div
                          initial={{ opacity: 0, y: -10 }}
                          animate={{ opacity: 1, y: 0 }}
                          exit={{ opacity: 0, y: -10 }}
                          className='hidden md:block absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2 px-3 py-2 bg-gray-900 dark:bg-white text-white dark:text-gray-900 rounded-lg text-xs z-50 pointer-events-none shadow-lg max-w-xs'>
                          <div className='font-semibold'>{getStatusLabel(currentStatus)}</div>
                          <div className='text-xs opacity-90'>{getDayCapacityLabel(day.capacity)}</div>
                          {day.projectsCount > 0 && (
                            <div className='text-xs opacity-90 mt-1 space-y-1'>
                              <div className='font-medium'>
                                {day.projectsCount} project{day.projectsCount !== 1 ? 's' : ''}
                              </div>
                              {day.projectTitles &&
                                day.projectTitles.slice(0, 3).map((proj, idx) => (
                                  <div key={idx} className='text-xs truncate opacity-90'>
                                    ΓÇó {proj.title}
                                  </div>
                                ))}
                              {day.projectTitles && day.projectTitles.length > 3 && <div className='text-xs opacity-75'>+{day.projectTitles.length - 3} more</div>}
                            </div>
                          )}
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </>
                )}
              </motion.div>
            )
          })}
        </AnimatePresence>
      </div>

      {/* Summary Stats - only for own profile, hidden in edit mode */}
      {!isPublicView && !editMode && (
        <div className='mt-6 pt-6 border-t theme-border grid grid-cols-2 md:grid-cols-4 gap-2 md:gap-4'>
          {[
            { label: 'Available', value: calendarData.daysBreakdown?.green || 0, statusColor: 'green' },
            { label: 'Partially Busy', value: calendarData.daysBreakdown?.yellow || 0, statusColor: 'yellow' },
            { label: 'Busy', value: calendarData.daysBreakdown?.orange || 0, statusColor: 'orange' },
            { label: 'Fully Busy', value: calendarData.daysBreakdown?.red || 0, statusColor: 'red' }
          ].map((stat) => (
            <div key={stat.label} className='p-2 md:p-3 rounded-lg theme-card border theme-border'>
              <div className='text-xs theme-text-secondary'>{stat.label}</div>
              <div className='text-lg md:text-xl font-bold theme-text'>{stat.value}</div>
              <div className='mt-1 w-2 h-2 rounded-full' style={{ backgroundColor: getStatusColor(stat.statusColor) }}></div>
            </div>
          ))}
        </div>
      )}

      {/* Edit Panel - only in edit mode */}
      {editMode && <AvailabilityEditPanel selectedDays={selectedDays} onStatusChange={onStatusChange} onSave={onSaveChanges} onCancel={onCancel} saving={saving} />}
    </motion.div>
  )
}

DetailedCalendarView.propTypes = {
  calendarData: PropTypes.object.isRequired,
  isOwnProfile: PropTypes.bool,
  isPublicView: PropTypes.bool,
  isPublic: PropTypes.bool,
  editMode: PropTypes.bool,
  selectedDays: PropTypes.object,
  saving: PropTypes.bool,
  togglingVisibility: PropTypes.bool,
  statusFilter: PropTypes.string,
  filterLoading: PropTypes.bool,
  optimisticUpdates: PropTypes.object,
  hoveredDay: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
  onPreviousMonth: PropTypes.func.isRequired,
  onNextMonth: PropTypes.func.isRequired,
  onEditMode: PropTypes.func,
  onHandleToggleVisibility: PropTypes.func,
  onStatusFilterChange: PropTypes.func,
  onClearFilter: PropTypes.func,
  onDayClick: PropTypes.func,
  onStatusChange: PropTypes.func,
  onSaveChanges: PropTypes.func,
  onCancel: PropTypes.func,
  onHoveredDay: PropTypes.func,
  getStatusColor: PropTypes.func.isRequired,
  getStatusLabel: PropTypes.func.isRequired,
  getDayCapacityLabel: PropTypes.func
}

export default DetailedCalendarView

import { motion, AnimatePresence } from 'framer-motion'
import PropTypes from 'prop-types'
import { FaChevronLeft, FaTimes } from 'react-icons/fa'
import { ProjectFilterPanel } from './ProjectFilterPanel'

const FilterSidebar = ({ isOpen, onToggle, onClose, filters, onFilterChange, onClearAll, hasActiveFilters, isDarkMode }) => {
  return (
    <>
      {/* Mobile Toggle Button */}
      <div className='lg:hidden fixed top-24 left-4 z-40'>
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={onToggle}
          className={`p-3 rounded-lg shadow-lg transition-colors bg-accent text-white hover:bg-accent/80 ${hasActiveFilters ? 'ring-2 ring-accent ring-offset-2 dark:ring-offset-primary ring-offset-light' : ''}`}
          aria-label='Toggle filters'>
          <svg className='w-5 h-5' fill='none' stroke='currentColor' viewBox='0 0 24 24'>
            <path
              strokeLinecap='round'
              strokeLinejoin='round'
              strokeWidth={2}
              d='M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z'
            />
          </svg>
        </motion.button>
      </div>

      {/* Mobile Overlay */}
      <AnimatePresence>
        {isOpen && <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose} className='lg:hidden fixed inset-0 bg-black bg-opacity-50 z-30 top-16' />}
      </AnimatePresence>

      {/* Sidebar Container */}
      <motion.div
        initial={{ x: '-100%' }}
        animate={{ x: isOpen ? 0 : '-100%' }}
        exit={{ x: '-100%' }}
        transition={{ type: 'spring', stiffness: 300, damping: 30 }}
        className={`
          fixed lg:relative lg:translate-x-0
          top-24 left-0 h-[calc(100vh-6rem)] lg:h-auto
          w-80 lg:w-64
          z-40 lg:z-0
          overflow-y-auto lg:overflow-visible
          bg-light dark:bg-primary
          border-r border-primary/10 dark:border-light/10
          shadow-xl lg:shadow-none p-4 lg:p-0
        `>
        {/* Header with Close Button */}
        <div
          className={`
            sticky top-0 z-50 p-4 border-b
            bg-light dark:bg-primary border-primary/10 dark:border-light/10
            lg:hidden
          `}>
          <div className='flex items-center justify-between'>
            <h2 className={`text-lg font-semibold theme-text`}>Filters</h2>
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              onClick={onClose}
              className={`p-2 rounded-lg hover:bg-primary/10 dark:hover:bg-light/10 theme-text-secondary hover:text-accent transition-colors`}
              aria-label='Close filters'>
              <FaTimes />
            </motion.button>
          </div>
        </div>

        {/* Filter Panel */}
        <div className='p-4 lg:p-0'>
          <ProjectFilterPanel filters={filters} onFilterChange={onFilterChange} onClearAll={onClearAll} hasActiveFilters={hasActiveFilters} />
        </div>
      </motion.div>
    </>
  )
}

FilterSidebar.propTypes = {
  isOpen: PropTypes.bool.isRequired,
  onToggle: PropTypes.func.isRequired,
  onClose: PropTypes.func.isRequired,
  filters: PropTypes.object.isRequired,
  onFilterChange: PropTypes.func.isRequired,
  onClearAll: PropTypes.func.isRequired,
  hasActiveFilters: PropTypes.bool,
  isDarkMode: PropTypes.bool
}

export default FilterSidebar
